window.VET_CONTENT = {"version":1,"title":"Bibia Estudos","chapters":[{"id":1,"title":"Mecanismos de defesa e imunidade inata","group":"Imunologia","summary":["Barreiras limitam a entrada de agentes.","A resposta inata é rápida e reconhece padrões de perigo.","A resposta adaptativa é específica e forma memória."],"lesson":[{"type":"p","html":"As defesas do organismo envolvem barreiras, resposta inata e resposta adaptativa."},{"type":"heading","text":"1.1 Complete as frases."},{"type":"p","html":"a) Pele, mucosas e microbiota constituem a primeira linha de <b>defesa</b>."},{"type":"p","html":"b) A imunidade <b>inata</b> apresenta resposta rápida e pouco específica."},{"type":"p","html":"c) A imunidade <b>adaptativa</b> é específica e apresenta memória."},{"type":"p","html":"d) Os padrões moleculares associados a patógenos são chamados de <b>PAMPs</b>."},{"type":"p","html":"e) Moléculas liberadas por tecidos lesionados são chamadas de <b>DAMPs</b>."},{"type":"heading","text":"1.2 Relacione as colunas."},{"type":"p","html":"<b>(1) Macrófagos e células dendríticas<br/>(2) Neutrófilos<br/>(3) Linfócitos T e B<br/>(4) Pele e mucosas</b>"},{"type":"p","html":"<b>(3)</b> Participam da imunidade adaptativa."},{"type":"p","html":"<b>(4)</b> Atuam como barreiras físicas."},{"type":"p","html":"<b>(2)</b> São importantes na resposta inflamatória inicial."},{"type":"p","html":"<b>(1)</b> Atuam como células sentinelas."},{"type":"heading","text":"1.3 Situação-problema"},{"type":"p","html":"Um cão apresenta uma lesão de pele com recrutamento rápido de células inflamatórias."},{"type":"qa","question":"a) Qual tipo de imunidade atua inicialmente?","answer":"A imunidade inata, que atua rapidamente por meio de reconhecimento de sinais de lesão e de patógenos, inflamação e recrutamento celular."},{"type":"qa","question":"b) A resposta inicial depende de contato prévio com o mesmo agente? Explique.","answer":"Não. Ela não exige exposição anterior ao mesmo agente; reconhece padrões e sinais de perigo. A memória específica é característica da imunidade adaptativa."}],"questions":[{"id":"1.1-f1","ref":"1.1","type":"fill","prompt":"Pele, mucosas e microbiota constituem a primeira linha de ____.","answers":[["defesa","proteção","protecao"]],"explanation":"a) Pele, mucosas e microbiota constituem a primeira linha de defesa.","referenceAnswers":["defesa"]},{"id":"1.1-f2","ref":"1.1","type":"fill","prompt":"A imunidade ____ apresenta resposta rápida e pouco específica.","answers":[["inata","imunidade inata"]],"explanation":"b) A imunidade inata apresenta resposta rápida e pouco específica.","referenceAnswers":["inata"]},{"id":"1.1-f3","ref":"1.1","type":"fill","prompt":"A imunidade ____ é específica e apresenta memória.","answers":[["adaptativa","imunidade adaptativa","adquirida"]],"explanation":"c) A imunidade adaptativa é específica e apresenta memória.","referenceAnswers":["adaptativa"]},{"id":"1.1-f4","ref":"1.1","type":"fill","prompt":"Os padrões moleculares associados a patógenos são chamados de ____.","answers":[["PAMPs","PAMP"]],"explanation":"d) Os padrões moleculares associados a patógenos são chamados de PAMPs.","referenceAnswers":["PAMPs"]},{"id":"1.1-f5","ref":"1.1","type":"fill","prompt":"Moléculas liberadas por tecidos lesionados são chamadas de ____.","answers":[["DAMPs","DAMP"]],"explanation":"e) Moléculas liberadas por tecidos lesionados são chamadas de DAMPs.","referenceAnswers":["DAMPs"]},{"id":"1.2-match","ref":"1.2","type":"match","prompt":"Relacione cada descrição ao conceito correto.","labels":["Macrófagos e células dendríticas","Neutrófilos","Linfócitos T e B","Pele e mucosas"],"pairs":[{"text":"Participam da imunidade adaptativa.","answer":"3"},{"text":"Atuam como barreiras físicas.","answer":"4"},{"text":"São importantes na resposta inflamatória inicial.","answer":"2"},{"text":"Atuam como células sentinelas.","answer":"1"}],"explanation":"Linfócitos T e B: Participam da imunidade adaptativa. | Pele e mucosas: Atuam como barreiras físicas. | Neutrófilos: São importantes na resposta inflamatória inicial. | Macrófagos e células dendríticas: Atuam como células sentinelas."},{"id":"1.3-a","ref":"1.3a","type":"choice","prompt":"Qual tipo de imunidade atua inicialmente?","context":"Um cão apresenta uma lesão de pele com recrutamento rápido de células inflamatórias.","options":["Imunidade inata","Imunidade adaptativa de memória","Somente anticorpos IgG","Somente linfócitos B de memória"],"answer":"Imunidade inata","explanation":"A imunidade inata, que atua rapidamente por meio de reconhecimento de sinais de lesão e de patógenos, inflamação e recrutamento celular."},{"id":"1.3-b","ref":"1.3b","type":"choice","prompt":"A resposta inicial depende de contato prévio com o mesmo agente? Explique.","context":"Um cão apresenta uma lesão de pele com recrutamento rápido de células inflamatórias.","options":["Não exige contato anterior","Exige vacinação prévia","Exige anticorpos específicos prévios","Depende de memória específica"],"answer":"Não exige contato anterior","explanation":"Não. Ela não exige exposição anterior ao mesmo agente; reconhece padrões e sinais de perigo. A memória específica é característica da imunidade adaptativa."}]},{"id":2,"title":"Inflamação, proteínas de fase aguda e complemento","group":"Imunologia","summary":["Inflamação não significa necessariamente infecção.","Complemento: opsonização, inflamação e lise.","Vias: clássica, alternativa e lectina."],"lesson":[{"type":"heading","text":"2.1 Complete."},{"type":"p","html":"a) As proteínas de fase aguda são produzidas principalmente pelo <b>fígado</b>."},{"type":"p","html":"b) Sua produção é estimulada por <b>citocinas</b> inflamatórias."},{"type":"p","html":"c) Dois exemplos são <b>fibrinogênio</b> e <b>proteína C reativa</b>."},{"type":"p","html":"d) A febre pode ocorrer em processos <b>inflamatórios</b>, mesmo sem infecção."},{"type":"heading","text":"2.2 Relacione as vias de ativação do complemento."},{"type":"p","html":"<b>(1) Clássica<br/>(2) Alternativa<br/>(3) Lectina</b>"},{"type":"p","html":"<b>(2)</b> Ativação diretamente na superfície de patógenos."},{"type":"p","html":"<b>(3)</b> Ligação da lectina a açúcares, como a manose."},{"type":"p","html":"<b>(1)</b> Ativação por complexos antígeno-anticorpo."},{"type":"heading","text":"2.3 Complete as funções."},{"type":"p","html":"a) O revestimento que facilita a fagocitose é chamado de <b>opsonização</b>."},{"type":"p","html":"b) O recrutamento orientado de células é chamado de <b>quimiotaxia</b>."},{"type":"p","html":"c) Os componentes terminais formam o <b>Complexo de Ataque à Membrana</b>, abreviado como MAC."},{"type":"p","html":"d) O MAC pode produzir <b>lise</b> osmótica no patógeno."},{"type":"p","html":"e) Fragmentos como C3a e C5a contribuem para a <b>inflamação</b>."},{"type":"heading","text":"2.4 Responda com suas palavras."},{"type":"qa","question":"a) Como o complemento conecta a defesa contra patógenos e a inflamação?","answer":"O complemento favorece a opsonização e pode causar lise de alvos pelo MAC. Seus fragmentos também promovem inflamação e recrutamento de células de defesa."},{"type":"qa","question":"b) Um animal com febre tem necessariamente uma infecção? Justifique.","answer":"Não. A febre também pode acompanhar inflamação sem infecção; portanto, isoladamente, não identifica a causa do processo."}],"questions":[{"id":"2.1-f1","ref":"2.1","type":"fill","prompt":"As proteínas de fase aguda são produzidas principalmente pelo ____.","answers":[["fígado","figado"]],"explanation":"a) As proteínas de fase aguda são produzidas principalmente pelo fígado.","referenceAnswers":["fígado"]},{"id":"2.1-f2","ref":"2.1","type":"fill","prompt":"Sua produção é estimulada por ____ inflamatórias.","answers":[["citocinas","citocina"]],"explanation":"b) Sua produção é estimulada por citocinas inflamatórias.","referenceAnswers":["citocinas"]},{"id":"2.1-f3","ref":"2.1","type":"fill","prompt":"Dois exemplos são ____ e ____.","answers":[["fibrinogênio","proteína C reativa","PCR"],["fibrinogênio","proteína C reativa","PCR"]],"explanation":"c) Dois exemplos são fibrinogênio e proteína C reativa.","referenceAnswers":["fibrinogênio","proteína C reativa"],"distinct":true,"distinctGroups":[["fibrinogênio"],["proteína C reativa","PCR"]]},{"id":"2.1-f5","ref":"2.1","type":"fill","prompt":"A febre pode ocorrer em processos ____, mesmo sem infecção.","answers":[["inflamatórios","inflamatorios","inflamatórias","inflamatorias"]],"explanation":"d) A febre pode ocorrer em processos inflamatórios, mesmo sem infecção.","referenceAnswers":["inflamatórios"]},{"id":"2.2-match","ref":"2.2","type":"match","prompt":"Relacione cada descrição ao conceito correto.","labels":["Clássica","Alternativa","Lectina"],"pairs":[{"text":"Ativação diretamente na superfície de patógenos.","answer":"2"},{"text":"Ligação da lectina a açúcares, como a manose.","answer":"3"},{"text":"Ativação por complexos antígeno-anticorpo.","answer":"1"}],"explanation":"Alternativa: Ativação diretamente na superfície de patógenos. | Lectina: Ligação da lectina a açúcares, como a manose. | Clássica: Ativação por complexos antígeno-anticorpo."},{"id":"2.3-f1","ref":"2.3","type":"fill","prompt":"O revestimento que facilita a fagocitose é chamado de ____.","answers":[["opsonização","opsonizacao"]],"explanation":"a) O revestimento que facilita a fagocitose é chamado de opsonização.","referenceAnswers":["opsonização"]},{"id":"2.3-f2","ref":"2.3","type":"fill","prompt":"O recrutamento orientado de células é chamado de ____.","answers":[["quimiotaxia","quimiotaxis"]],"explanation":"b) O recrutamento orientado de células é chamado de quimiotaxia.","referenceAnswers":["quimiotaxia"]},{"id":"2.3-f3","ref":"2.3","type":"fill","prompt":"Os componentes terminais formam o ____, abreviado como MAC.","answers":[["Complexo de Ataque à Membrana","MAC","complexo de ataque a membrana"]],"explanation":"c) Os componentes terminais formam o Complexo de Ataque à Membrana, abreviado como MAC.","referenceAnswers":["Complexo de Ataque à Membrana"]},{"id":"2.3-f4","ref":"2.3","type":"fill","prompt":"O MAC pode produzir ____ osmótica no patógeno.","answers":[["lise"]],"explanation":"d) O MAC pode produzir lise osmótica no patógeno.","referenceAnswers":["lise"]},{"id":"2.3-f5","ref":"2.3","type":"fill","prompt":"Fragmentos como C3a e C5a contribuem para a ____.","answers":[["inflamação","inflamacao"]],"explanation":"e) Fragmentos como C3a e C5a contribuem para a inflamação.","referenceAnswers":["inflamação"]},{"id":"2.4-a","ref":"2.4a","type":"choice","prompt":"Como o complemento conecta a defesa contra patógenos e a inflamação?","context":"","options":["Opsonização, lise e recrutamento inflamatório","Somente produção de anticorpos","Somente maturação dos linfócitos no timo","Inibição de toda inflamação"],"answer":"Opsonização, lise e recrutamento inflamatório","explanation":"O complemento favorece a opsonização e pode causar lise de alvos pelo MAC. Seus fragmentos também promovem inflamação e recrutamento de células de defesa."},{"id":"2.4-b","ref":"2.4b","type":"choice","prompt":"Um animal com febre tem necessariamente uma infecção? Justifique.","context":"","options":["Não; inflamação sem infecção também pode causar febre","Sim; febre sempre comprova infecção","Sim; febre sempre comprova virose","Não; febre exclui qualquer infecção"],"answer":"Não; inflamação sem infecção também pode causar febre","explanation":"Não. A febre também pode acompanhar inflamação sem infecção; portanto, isoladamente, não identifica a causa do processo."}]},{"id":3,"title":"Linfócitos T e B e apresentação de antígenos","group":"Imunologia","summary":["MHC I apresenta para T CD8+; MHC II para T CD4+.","Plasmócitos produzem anticorpos.","Th1, Th2, Th17 e Treg coordenam respostas diferentes."],"lesson":[{"type":"heading","text":"3.1 Complete."},{"type":"p","html":"a) Os linfócitos T se originam na <b>medula óssea</b> e maturam no <b>timo</b>."},{"type":"p","html":"b) Os T CD4+ reconhecem antígenos apresentados pelo MHC de classe <b>II</b>."},{"type":"p","html":"c) Os T CD8+ reconhecem antígenos apresentados pelo MHC de classe <b>I</b>."},{"type":"p","html":"d) Linfócitos B ativados podem formar <b>plasmócitos</b>, que secretam anticorpos, e células B de <b>memória</b>."},{"type":"heading","text":"3.2 Relacione."},{"type":"p","html":"<b>(1) T CD4+<br/>(2) T CD8+<br/>(3) Plasmócitos<br/>(4) MHC</b>"},{"type":"p","html":"<b>(4)</b> Apresenta antígenos aos linfócitos T."},{"type":"p","html":"<b>(3)</b> Produzem anticorpos."},{"type":"p","html":"<b>(1)</b> Secretam citocinas e coordenam outras células imunes."},{"type":"p","html":"<b>(2)</b> Destroem células infectadas ou anormais."},{"type":"heading","text":"3.3 Identifique os subtipos de T auxiliares."},{"type":"p","html":"a) Predomínio de resposta celular: <b>Th1</b>."},{"type":"p","html":"b) Resposta humoral e contra parasitas: <b>Th2</b>."},{"type":"p","html":"c) Defesa contra fungos e bactérias extracelulares: <b>Th17</b>."},{"type":"p","html":"d) Regulação e supressão da resposta imune: <b>Treg</b>."},{"type":"heading","text":"3.4 Situação-problema"},{"type":"p","html":"Uma célula infectada apresenta antígenos pelo MHC de classe I."},{"type":"qa","question":"a) Qual população de linfócitos T pode reconhecer essa apresentação?","answer":"Linfócitos T CD8+, também chamados de citotóxicos."},{"type":"qa","question":"b) Qual é a principal ação dessa população sobre a célula infectada?","answer":"Reconhecer e destruir a célula infectada ou anormal, limitando a permanência do agente no organismo."}],"questions":[{"id":"3.1-f1","ref":"3.1","type":"fill","prompt":"Os linfócitos T se originam na ____ e maturam no ____.","answers":[["medula óssea","medula ossea"],["timo"]],"explanation":"a) Os linfócitos T se originam na medula óssea e maturam no timo.","referenceAnswers":["medula óssea","timo"]},{"id":"3.1-f3","ref":"3.1","type":"fill","prompt":"Os T CD4+ reconhecem antígenos apresentados pelo MHC de classe ____.","answers":[["II","2","classe II","classe 2"]],"explanation":"b) Os T CD4+ reconhecem antígenos apresentados pelo MHC de classe II.","referenceAnswers":["II"]},{"id":"3.1-f4","ref":"3.1","type":"fill","prompt":"Os T CD8+ reconhecem antígenos apresentados pelo MHC de classe ____.","answers":[["I","1","classe I","classe 1"]],"explanation":"c) Os T CD8+ reconhecem antígenos apresentados pelo MHC de classe I.","referenceAnswers":["I"]},{"id":"3.1-f5","ref":"3.1","type":"fill","prompt":"Linfócitos B ativados podem formar ____, que secretam anticorpos, e células B de ____.","answers":[["plasmócitos","plasmocitos","plasmócito"],["memória","memoria"]],"explanation":"d) Linfócitos B ativados podem formar plasmócitos, que secretam anticorpos, e células B de memória.","referenceAnswers":["plasmócitos","memória"]},{"id":"3.2-match","ref":"3.2","type":"match","prompt":"Relacione cada descrição ao conceito correto.","labels":["T CD4+","T CD8+","Plasmócitos","MHC"],"pairs":[{"text":"Apresenta antígenos aos linfócitos T.","answer":"4"},{"text":"Produzem anticorpos.","answer":"3"},{"text":"Secretam citocinas e coordenam outras células imunes.","answer":"1"},{"text":"Destroem células infectadas ou anormais.","answer":"2"}],"explanation":"MHC: Apresenta antígenos aos linfócitos T. | Plasmócitos: Produzem anticorpos. | T CD4+: Secretam citocinas e coordenam outras células imunes. | T CD8+: Destroem células infectadas ou anormais."},{"id":"3.3-f1","ref":"3.3","type":"fill","prompt":"Predomínio de resposta celular: ____.","answers":[["Th1"]],"explanation":"a) Predomínio de resposta celular: Th1.","referenceAnswers":["Th1"]},{"id":"3.3-f2","ref":"3.3","type":"fill","prompt":"Resposta humoral e contra parasitas: ____.","answers":[["Th2"]],"explanation":"b) Resposta humoral e contra parasitas: Th2.","referenceAnswers":["Th2"]},{"id":"3.3-f3","ref":"3.3","type":"fill","prompt":"Defesa contra fungos e bactérias extracelulares: ____.","answers":[["Th17"]],"explanation":"c) Defesa contra fungos e bactérias extracelulares: Th17.","referenceAnswers":["Th17"]},{"id":"3.3-f4","ref":"3.3","type":"fill","prompt":"Regulação e supressão da resposta imune: ____.","answers":[["Treg"]],"explanation":"d) Regulação e supressão da resposta imune: Treg.","referenceAnswers":["Treg"]},{"id":"3.4-a","ref":"3.4a","type":"choice","prompt":"Qual população de linfócitos T pode reconhecer essa apresentação?","context":"Uma célula infectada apresenta antígenos pelo MHC de classe I.","options":["Linfócitos T CD8+","Linfócitos T CD4+","Plasmócitos","Linfócitos B de memória"],"answer":"Linfócitos T CD8+","explanation":"Linfócitos T CD8+, também chamados de citotóxicos."},{"id":"3.4-b","ref":"3.4b","type":"choice","prompt":"Qual é a principal ação dessa população sobre a célula infectada?","context":"Uma célula infectada apresenta antígenos pelo MHC de classe I.","options":["Destruir a célula infectada","Secretar anticorpos contra a célula","Produzir colostro","Transformar a célula em plasmócito"],"answer":"Destruir a célula infectada","explanation":"Reconhecer e destruir a célula infectada ou anormal, limitando a permanência do agente no organismo."}]},{"id":4,"title":"Anticorpos: classes e funções","group":"Imunologia","summary":["IgM inicia a resposta primária; IgG se destaca na secundária.","IgA protege mucosas; IgE participa de alergias e defesa contra helmintos.","Neutralização, opsonização, ADCC e complemento são funções distintas."],"lesson":[{"type":"p","html":"Os anticorpos são imunoglobulinas produzidas por plasmócitos."},{"type":"heading","text":"4.1 Complete a tabela com a classe correspondente."},{"type":"table","headers":["Característica predominante","Classe"],"rows":[["Primeira classe na resposta primária; ativa bem o complemento.","IgM"],["Mais abundante no sangue; importante na resposta secundária.","IgG"],["Predomina em secreções e protege as mucosas.","IgA"],["Relacionada a alergias, helmintos, mastócitos e basófilos.","IgE"],["Atua principalmente como receptor de linfócitos B maduros.","IgD"]]},{"type":"heading","text":"4.2 Relacione as funções dos anticorpos."},{"type":"p","html":"<b>(1) Neutralização<br/>(2) Opsonização<br/>(3) ADCC<br/>(4) Ativação do complemento</b>"},{"type":"p","html":"<b>(2)</b> Anticorpos revestem alvos e favorecem sua fagocitose."},{"type":"p","html":"<b>(3)</b> Células NK reconhecem alvos revestidos por anticorpos e promovem sua destruição."},{"type":"p","html":"<b>(1)</b> Bloqueio da entrada de microrganismos nas células e da ação de toxinas."},{"type":"p","html":"<b>(4)</b> Início de uma cascata que pode favorecer inflamação e lise."},{"type":"heading","text":"4.3 Responda."},{"type":"qa","question":"a) Qual é o papel dos receptores Fc na opsonização?","answer":"Os receptores Fc de macrófagos e neutrófilos reconhecem a região Fc dos anticorpos que revestem o alvo e facilitam sua fagocitose."},{"type":"qa","question":"b) Diferencie a ação de células NK na ADCC da ação do MAC.","answer":"Na ADCC, uma célula NK reconhece anticorpos ligados ao alvo e promove sua morte. O MAC é um complexo de proteínas do complemento que forma poros na membrana de alvos suscetíveis."},{"type":"qa","question":"c) Qual imunoglobulina predomina na proteção das mucosas?","answer":"IgA."}],"questions":[{"id":"4.1-t1","ref":"4.1","type":"fill","prompt":"Qual é a classe correspondente? Primeira classe na resposta primária; ativa bem o complemento. ____","answers":[["IgM"]],"explanation":"Primeira classe na resposta primária; ativa bem o complemento.: IgM.","referenceAnswers":["IgM"]},{"id":"4.1-t2","ref":"4.1","type":"fill","prompt":"Qual é a classe correspondente? Mais abundante no sangue; importante na resposta secundária. ____","answers":[["IgG"]],"explanation":"Mais abundante no sangue; importante na resposta secundária.: IgG.","referenceAnswers":["IgG"]},{"id":"4.1-t3","ref":"4.1","type":"fill","prompt":"Qual é a classe correspondente? Predomina em secreções e protege as mucosas. ____","answers":[["IgA"]],"explanation":"Predomina em secreções e protege as mucosas.: IgA.","referenceAnswers":["IgA"]},{"id":"4.1-t4","ref":"4.1","type":"fill","prompt":"Qual é a classe correspondente? Relacionada a alergias, helmintos, mastócitos e basófilos. ____","answers":[["IgE"]],"explanation":"Relacionada a alergias, helmintos, mastócitos e basófilos.: IgE.","referenceAnswers":["IgE"]},{"id":"4.1-t5","ref":"4.1","type":"fill","prompt":"Qual é a classe correspondente? Atua principalmente como receptor de linfócitos B maduros. ____","answers":[["IgD"]],"explanation":"Atua principalmente como receptor de linfócitos B maduros.: IgD.","referenceAnswers":["IgD"]},{"id":"4.2-match","ref":"4.2","type":"match","prompt":"Relacione cada descrição ao conceito correto.","labels":["Neutralização","Opsonização","ADCC","Ativação do complemento"],"pairs":[{"text":"Anticorpos revestem alvos e favorecem sua fagocitose.","answer":"2"},{"text":"Células NK reconhecem alvos revestidos por anticorpos e promovem sua destruição.","answer":"3"},{"text":"Bloqueio da entrada de microrganismos nas células e da ação de toxinas.","answer":"1"},{"text":"Início de uma cascata que pode favorecer inflamação e lise.","answer":"4"}],"explanation":"Opsonização: Anticorpos revestem alvos e favorecem sua fagocitose. | ADCC: Células NK reconhecem alvos revestidos por anticorpos e promovem sua destruição. | Neutralização: Bloqueio da entrada de microrganismos nas células e da ação de toxinas. | Ativação do complemento: Início de uma cascata que pode favorecer inflamação e lise."},{"id":"4.3-a","ref":"4.3a","type":"choice","prompt":"Qual é o papel dos receptores Fc na opsonização?","context":"","options":["Reconhecer anticorpos ligados ao alvo e facilitar a fagocitose","Produzir antígenos no patógeno","Impedir a ligação de anticorpos","Maturar linfócitos T no timo"],"answer":"Reconhecer anticorpos ligados ao alvo e facilitar a fagocitose","explanation":"Os receptores Fc de macrófagos e neutrófilos reconhecem a região Fc dos anticorpos que revestem o alvo e facilitam sua fagocitose."},{"id":"4.3-b","ref":"4.3b","type":"choice","prompt":"Diferencie a ação de células NK na ADCC da ação do MAC.","context":"","options":["NK executa morte celular; MAC forma poros na membrana","NK produz IgA; MAC produz IgG","NK forma poros do complemento; MAC é um linfócito","NK e MAC são duas classes de anticorpos"],"answer":"NK executa morte celular; MAC forma poros na membrana","explanation":"Na ADCC, uma célula NK reconhece anticorpos ligados ao alvo e promove sua morte. O MAC é um complexo de proteínas do complemento que forma poros na membrana de alvos suscetíveis."},{"id":"4.3-c","ref":"4.3c","type":"choice","prompt":"Qual imunoglobulina predomina na proteção das mucosas?","context":"","options":["IgA","IgM","IgE","IgD"],"answer":"IgA","explanation":"IgA."}]},{"id":5,"title":"Dinâmica da resposta imune","group":"Imunologia","summary":["Memória torna a resposta secundária mais rápida e duradoura.","IgM e IgG precisam de contexto para interpretação.","Reconhecer uma resposta não é o mesmo que saber explicá-la."],"lesson":[{"type":"p","html":"A primeira exposição a um antígeno e as exposições posteriores produzem respostas diferentes."},{"type":"heading","text":"5.1 Compare as respostas."},{"type":"table","headers":["Aspecto","Primária","Secundária"],"rows":[["Contato com o antígeno","Primeiro contato","Contato posterior"],["Velocidade da resposta","Mais lenta","Mais rápida"],["Intensidade e duração","Menor pico; menos duradoura","Maior pico; mais duradoura"],["Classe predominante no modelo estudado","IgM, inicialmente","IgG, no modelo estudado"],["Participação da memória","Forma células de memória","Ativa células de memória existentes"]]},{"type":"heading","text":"5.2 Complete a sequência."},{"type":"p","html":"Primeiro contato com o antígeno → ativação de linfócitos → formação de células de <b>memória</b> → novo contato → resposta mais <b>rápida</b> e duradoura."},{"type":"heading","text":"5.3 Situação-problema"},{"type":"p","html":"Dois animais entram em contato com o mesmo antígeno. Um deles já havia sido exposto anteriormente; o outro nunca teve contato."},{"type":"qa","question":"a) Em qual animal se espera uma resposta mais rápida? Por quê?","answer":"No animal previamente exposto, por causa dos linfócitos de memória formados no primeiro contato."},{"type":"qa","question":"b) Qual classe de anticorpo tende a aparecer primeiro na resposta primária?","answer":"IgM."},{"type":"qa","question":"c) Qual classe tende a predominar na resposta secundária descrita no texto?","answer":"IgG, no modelo de resposta descrito no texto."},{"type":"heading","text":"5.4 Interpretação sorológica"},{"type":"qa","question":"Por que IgM e IgG podem auxiliar na avaliação da fase de uma infecção, mas não devem ser interpretadas isoladamente?","answer":"IgM pode sugerir resposta recente; IgG pode refletir exposição anterior e persistir por bastante tempo. A interpretação depende do agente, da vacinação, do momento da coleta e dos sinais clínicos. Uma única dosagem não define, por si só, infecção ativa ou crônica."},{"type":"heading","text":"5.5 Checklist de imunologia"},{"type":"p","html":"[  ] Diferencio barreiras, imunidade inata e adaptativa."},{"type":"p","html":"[  ] Explico as vias e as funções do complemento."},{"type":"p","html":"[  ] Relaciono MHC I/CD8+ e MHC II/CD4+."},{"type":"p","html":"[  ] Reconheço as classes de anticorpos e a memória imunológica."}],"questions":[{"id":"5.1-t1","ref":"5.1","type":"choice","prompt":"Qual comparação corresponde a \"Contato com o antígeno\"? Considere primária | secundária.","options":["Primeiro contato | Contato posterior","Mais lenta | Mais rápida","Menor pico; menos duradoura | Maior pico; mais duradoura","IgM, inicialmente | IgG, no modelo estudado"],"answer":"Primeiro contato | Contato posterior","explanation":"Primeiro contato | Contato posterior"},{"id":"5.1-t2","ref":"5.1","type":"choice","prompt":"Qual comparação corresponde a \"Velocidade da resposta\"? Considere primária | secundária.","options":["Mais lenta | Mais rápida","Primeiro contato | Contato posterior","Menor pico; menos duradoura | Maior pico; mais duradoura","IgM, inicialmente | IgG, no modelo estudado"],"answer":"Mais lenta | Mais rápida","explanation":"Mais lenta | Mais rápida"},{"id":"5.1-t3","ref":"5.1","type":"choice","prompt":"Qual comparação corresponde a \"Intensidade e duração\"? Considere primária | secundária.","options":["Menor pico; menos duradoura | Maior pico; mais duradoura","Primeiro contato | Contato posterior","Mais lenta | Mais rápida","IgM, inicialmente | IgG, no modelo estudado"],"answer":"Menor pico; menos duradoura | Maior pico; mais duradoura","explanation":"Menor pico; menos duradoura | Maior pico; mais duradoura"},{"id":"5.1-t4","ref":"5.1","type":"choice","prompt":"Qual comparação corresponde a \"Classe predominante no modelo estudado\"? Considere primária | secundária.","options":["IgM, inicialmente | IgG, no modelo estudado","Primeiro contato | Contato posterior","Mais lenta | Mais rápida","Menor pico; menos duradoura | Maior pico; mais duradoura"],"answer":"IgM, inicialmente | IgG, no modelo estudado","explanation":"IgM, inicialmente | IgG, no modelo estudado"},{"id":"5.1-t5","ref":"5.1","type":"choice","prompt":"Qual comparação corresponde a \"Participação da memória\"? Considere primária | secundária.","options":["Forma células de memória | Ativa células de memória existentes","Primeiro contato | Contato posterior","Mais lenta | Mais rápida","Menor pico; menos duradoura | Maior pico; mais duradoura"],"answer":"Forma células de memória | Ativa células de memória existentes","explanation":"Forma células de memória | Ativa células de memória existentes"},{"id":"5.2-f1","ref":"5.2","type":"fill","prompt":"Primeiro contato com o antígeno → ativação de linfócitos → formação de células de ____ → novo contato → resposta mais ____ e duradoura.","answers":[["memória","memoria"],["rápida"]],"explanation":"Primeiro contato com o antígeno → ativação de linfócitos → formação de células de memória → novo contato → resposta mais rápida e duradoura.","referenceAnswers":["memória","rápida"]},{"id":"5.3-a","ref":"5.3a","type":"choice","prompt":"Em qual animal se espera uma resposta mais rápida? Por quê?","context":"Dois animais entram em contato com o mesmo antígeno. Um deles já havia sido exposto anteriormente; o outro nunca teve contato.","options":["No previamente exposto, por causa da memória","No nunca exposto, por ter mais memória","Em ambos, sempre com a mesma velocidade","No nunca exposto, por não precisar de linfócitos"],"answer":"No previamente exposto, por causa da memória","explanation":"No animal previamente exposto, por causa dos linfócitos de memória formados no primeiro contato."},{"id":"5.3-b","ref":"5.3b","type":"choice","prompt":"Qual classe de anticorpo tende a aparecer primeiro na resposta primária?","context":"Dois animais entram em contato com o mesmo antígeno. Um deles já havia sido exposto anteriormente; o outro nunca teve contato.","options":["IgM","IgA","IgE","IgD"],"answer":"IgM","explanation":"IgM."},{"id":"5.3-c","ref":"5.3c","type":"choice","prompt":"Qual classe tende a predominar na resposta secundária descrita no texto?","context":"Dois animais entram em contato com o mesmo antígeno. Um deles já havia sido exposto anteriormente; o outro nunca teve contato.","options":["IgG","IgD","IgE","IgA"],"answer":"IgG","explanation":"IgG, no modelo de resposta descrito no texto."},{"id":"5.4-1","ref":"5.41","type":"choice","prompt":"Por que IgM e IgG podem auxiliar na avaliação da fase de uma infecção, mas não devem ser interpretadas isoladamente?","context":"","options":["Dependem do agente, da coleta, do histórico e dos sinais","IgG isolada sempre comprova infecção ativa","IgM isolada sempre comprova doença crônica","Dispensam qualquer avaliação clínica"],"answer":"Dependem do agente, da coleta, do histórico e dos sinais","explanation":"IgM pode sugerir resposta recente; IgG pode refletir exposição anterior e persistir por bastante tempo. A interpretação depende do agente, da vacinação, do momento da coleta e dos sinais clínicos. Uma única dosagem não define, por si só, infecção ativa ou crônica."}]},{"id":6,"title":"Hipersensibilidade alimentar canina","group":"Hipersensibilidade alimentar","summary":["Prurido não sazonal é um sinal frequente.","Eliminação por pelo menos 8 semanas, conforme o texto.","Provocação ajuda a confirmar a relação com o alimento."],"lesson":[{"type":"p","html":"É uma condição imunomediada que pode provocar sinais dermatológicos e gastrointestinais."},{"type":"heading","text":"6.1 Complete."},{"type":"p","html":"a) O prurido típico é <b>não sazonal</b>, ou seja, não depende de uma estação do ano."},{"type":"p","html":"b) Cite três alimentos mencionados como possíveis alérgenos: <b>carne bovina</b>, <b>frango</b> e <b>laticínios</b>."},{"type":"p","html":"c) Dois sinais gastrointestinais possíveis são <b>diarreia</b> e <b>vômito</b>."},{"type":"p","html":"d) Piodermite e <b>malasseziose</b> podem ocorrer como infecções secundárias."},{"type":"heading","text":"6.2 Diagnóstico e tratamento"},{"type":"qa","question":"a) Qual é o período mínimo de dieta de eliminação descrito no texto?","answer":"Pelo menos 8 semanas, conforme o texto, para avaliar os sinais dermatológicos."},{"type":"qa","question":"b) Quais características devem ter as fontes alimentares dessa dieta?","answer":"Fontes inéditas, nunca consumidas pelo animal, ou proteínas hidrolisadas. A dieta deve ser seguida de forma rigorosa, sem alimentos que prejudiquem o teste."},{"type":"qa","question":"c) Qual é a finalidade da dieta de provocação?","answer":"Reintroduzir o alimento suspeito e verificar a recorrência dos sinais, para confirmar sua relação com o quadro."},{"type":"qa","question":"d) Testes de IgE e intradérmicos confirmam o diagnóstico com boa confiabilidade?","answer":"Não. Têm baixa confiabilidade para confirmar hipersensibilidade alimentar. O diagnóstico se apoia na eliminação seguida de provocação."},{"type":"heading","text":"6.3 Situação-problema"},{"type":"p","html":"Um cão apresenta prurido durante todo o ano, eritema nas orelhas e diarreia ocasional. Melhora com a dieta de eliminação, mas volta a apresentar sinais após a reintrodução de um alimento suspeito."},{"type":"qa","question":"a) O que a recaída após a provocação ajuda a confirmar?","answer":"A relação entre o alimento reintroduzido e os sinais clínicos, ajudando a confirmar a hipersensibilidade alimentar."},{"type":"qa","question":"b) Qual deve ser a conduta dietética a longo prazo?","answer":"Excluir rigorosamente o alimento ou alérgeno identificado e manter uma dieta adequada; controlar também prurido e infecções secundárias."},{"type":"qa","question":"c) Como a adesão do tutor interfere no prognóstico?","answer":"A adesão rigorosa favorece o controle e um bom prognóstico. Exposições acidentais ou frequentes ao alérgeno podem causar recaídas."},{"type":"heading","text":"6.4 Checklist de hipersensibilidade alimentar"},{"type":"p","html":"[  ] Reconheço os sinais e as infecções secundárias."},{"type":"p","html":"[  ] Diferencio eliminação, provocação e manejo contínuo da dieta."}],"questions":[{"id":"6.1-f1","ref":"6.1","type":"fill","prompt":"O prurido típico é ____, ou seja, não depende de uma estação do ano.","answers":[["não sazonal","nao sazonal","nao-sazonal","não-sazonal"]],"explanation":"a) O prurido típico é não sazonal, ou seja, não depende de uma estação do ano.","referenceAnswers":["não sazonal"]},{"id":"6.1-f2","ref":"6.1","type":"fill","prompt":"Cite três alimentos mencionados como possíveis alérgenos: ____, ____ e ____.","answers":[["carne bovina","bovino","bovina","carne de boi","cordeiro","carne de cordeiro","frango","carne de frango","laticínios","leite","trigo"],["carne bovina","bovino","bovina","carne de boi","cordeiro","carne de cordeiro","frango","carne de frango","laticínios","leite","trigo"],["carne bovina","bovino","bovina","carne de boi","cordeiro","carne de cordeiro","frango","carne de frango","laticínios","leite","trigo"]],"explanation":"b) Cite três alimentos mencionados como possíveis alérgenos: carne bovina, frango e laticínios.","referenceAnswers":["carne bovina","frango","laticínios"],"distinct":true,"distinctGroups":[["carne bovina","bovino","bovina","carne de boi"],["cordeiro","carne de cordeiro"],["frango","carne de frango"],["laticínios","leite"],["trigo"]]},{"id":"6.1-f5","ref":"6.1","type":"fill","prompt":"Dois sinais gastrointestinais possíveis são ____ e ____.","answers":[["diarreia","diarréia","vômito","vômitos","dor abdominal"],["diarreia","diarréia","vômito","vômitos","dor abdominal"]],"explanation":"c) Dois sinais gastrointestinais possíveis são diarreia e vômito.","referenceAnswers":["diarreia","vômito"],"distinct":true,"distinctGroups":[["diarreia","diarréia"],["vômito","vômitos"],["dor abdominal"]]},{"id":"6.1-f7","ref":"6.1","type":"fill","prompt":"Piodermite e ____ podem ocorrer como infecções secundárias.","answers":[["malasseziose","malassezia"]],"explanation":"d) Piodermite e malasseziose podem ocorrer como infecções secundárias.","referenceAnswers":["malasseziose"]},{"id":"6.2-a","ref":"6.2a","type":"choice","prompt":"Qual é o período mínimo de dieta de eliminação descrito no texto?","context":"","options":["Pelo menos 8 semanas, conforme o texto","Apenas 24 horas","Apenas 3 dias","No máximo 1 semana"],"answer":"Pelo menos 8 semanas, conforme o texto","explanation":"Pelo menos 8 semanas, conforme o texto, para avaliar os sinais dermatológicos."},{"id":"6.2-b","ref":"6.2b","type":"choice","prompt":"Quais características devem ter as fontes alimentares dessa dieta?","context":"","options":["Fontes inéditas ou proteínas hidrolisadas","Qualquer alimento que o cão já consome","Somente os alimentos suspeitos","Dieta livre, com todos os petiscos habituais"],"answer":"Fontes inéditas ou proteínas hidrolisadas","explanation":"Fontes inéditas, nunca consumidas pelo animal, ou proteínas hidrolisadas. A dieta deve ser seguida de forma rigorosa, sem alimentos que prejudiquem o teste."},{"id":"6.2-c","ref":"6.2c","type":"choice","prompt":"Qual é a finalidade da dieta de provocação?","context":"","options":["Verificar a recaída após reintroduzir o alimento","Substituir a dieta de eliminação","Confirmar alergia apenas com um exame de sangue","Vacinar contra os alérgenos alimentares"],"answer":"Verificar a recaída após reintroduzir o alimento","explanation":"Reintroduzir o alimento suspeito e verificar a recorrência dos sinais, para confirmar sua relação com o quadro."},{"id":"6.2-d","ref":"6.2d","type":"choice","prompt":"Testes de IgE e intradérmicos confirmam o diagnóstico com boa confiabilidade?","context":"","options":["Não; eliminação e provocação são a base","Sim; IgE sempre confirma o alimento causador","Sim; teste intradérmico tem confirmação definitiva","Não; o diagnóstico dispensa qualquer dieta"],"answer":"Não; eliminação e provocação são a base","explanation":"Não. Têm baixa confiabilidade para confirmar hipersensibilidade alimentar. O diagnóstico se apoia na eliminação seguida de provocação."},{"id":"6.3-a","ref":"6.3a","type":"choice","prompt":"O que a recaída após a provocação ajuda a confirmar?","context":"Um cão apresenta prurido durante todo o ano, eritema nas orelhas e diarreia ocasional. Melhora com a dieta de eliminação, mas volta a apresentar sinais após a reintrodução de um alimento suspeito.","options":["Relação do alimento reintroduzido com os sinais","Ausência de reação ao alimento","Falha de todas as dietas hidrolisadas","Necessidade de revacinação"],"answer":"Relação do alimento reintroduzido com os sinais","explanation":"A relação entre o alimento reintroduzido e os sinais clínicos, ajudando a confirmar a hipersensibilidade alimentar."},{"id":"6.3-b","ref":"6.3b","type":"choice","prompt":"Qual deve ser a conduta dietética a longo prazo?","context":"Um cão apresenta prurido durante todo o ano, eritema nas orelhas e diarreia ocasional. Melhora com a dieta de eliminação, mas volta a apresentar sinais após a reintrodução de um alimento suspeito.","options":["Excluir rigorosamente o alérgeno identificado","Reintroduzir o alérgeno diariamente","Apenas controlar o prurido, sem mudar a dieta","Suspender todos os alimentos definitivamente"],"answer":"Excluir rigorosamente o alérgeno identificado","explanation":"Excluir rigorosamente o alimento ou alérgeno identificado e manter uma dieta adequada; controlar também prurido e infecções secundárias."},{"id":"6.3-c","ref":"6.3c","type":"choice","prompt":"Como a adesão do tutor interfere no prognóstico?","context":"Um cão apresenta prurido durante todo o ano, eritema nas orelhas e diarreia ocasional. Melhora com a dieta de eliminação, mas volta a apresentar sinais após a reintrodução de um alimento suspeito.","options":["Adesão rigorosa favorece controle e bom prognóstico","Petiscos com alérgeno não interferem","Adesão não muda o resultado","Exposição diária ao alérgeno sempre cura o quadro"],"answer":"Adesão rigorosa favorece controle e bom prognóstico","explanation":"A adesão rigorosa favorece o controle e um bom prognóstico. Exposições acidentais ou frequentes ao alérgeno podem causar recaídas."}]},{"id":7,"title":"Vacinação: objetivos, classificação e tecnologias","group":"Vacinação","summary":["A indicação depende do agente, do animal e da região.","Essenciais, não essenciais e não recomendadas são categorias diferentes.","Tecnologia e duração da proteção influenciam os reforços."],"lesson":[{"type":"p","html":"A partir desta seção, o guia reúne os conteúdos de vacinação de cães e gatos."},{"type":"heading","text":"7.1 Complete."},{"type":"p","html":"a) A vacinação busca proteger o animal e favorecer a imunidade de <b>rebanho</b>."},{"type":"p","html":"b) As recomendações globais devem ser adaptadas às condições <b>locais</b>."},{"type":"p","html":"c) Vacinas <b>essenciais</b> são fundamentais conforme a doença e o contexto."},{"type":"p","html":"d) Vacinas <b>não essenciais</b> dependem do estilo de vida, da região e da exposição."},{"type":"p","html":"e) Vacinas <b>não recomendadas</b> não apresentam evidências suficientes para justificar seu uso."},{"type":"heading","text":"7.2 Relacione as tecnologias."},{"type":"p","html":"<b>(1) Vivas modificadas (VVM)<br/>(2) Inativadas<br/>(3) Subunidades<br/>(4) Vetores<br/>(5) Ácidos nucleicos</b>"},{"type":"p","html":"<b>(3)</b> Contêm componentes específicos do patógeno."},{"type":"p","html":"<b>(5)</b> Utilizam DNA ou RNA; o texto descreve disponibilidade ainda limitada para cães e gatos."},{"type":"p","html":"<b>(1)</b> Em geral, são imunogênicas e induzem imunidade duradoura."},{"type":"p","html":"<b>(2)</b> Podem exigir múltiplas doses e adjuvantes."},{"type":"p","html":"<b>(4)</b> Transportam material genético de outro patógeno."},{"type":"heading","text":"7.3 Responda."},{"type":"qa","question":"a) O que significa duração da imunidade (DOI)?","answer":"DOI é o período durante o qual a imunização produz proteção contra a doença após a vacinação."},{"type":"qa","question":"b) Por que o protocolo deve considerar tanto o risco individual quanto o local?","answer":"O estilo de vida, a exposição, a idade e o histórico do animal se combinam com a ocorrência regional de doenças para determinar a indicação das vacinas."},{"type":"qa","question":"c) Vacinas essenciais e não essenciais têm sempre a mesma frequência de reforço? Explique.","answer":"Não. Algumas vacinas virais essenciais induzem proteção prolongada, enquanto diversas outras exigem reforços mais frequentes. A decisão depende do produto, da DOI, do risco e das normas locais."}],"questions":[{"id":"7.1-f1","ref":"7.1","type":"fill","prompt":"A vacinação busca proteger o animal e favorecer a imunidade de ____.","answers":[["rebanho","coletiva"]],"explanation":"a) A vacinação busca proteger o animal e favorecer a imunidade de rebanho.","referenceAnswers":["rebanho"]},{"id":"7.1-f2","ref":"7.1","type":"fill","prompt":"As recomendações globais devem ser adaptadas às condições ____.","answers":[["locais","local"]],"explanation":"b) As recomendações globais devem ser adaptadas às condições locais.","referenceAnswers":["locais"]},{"id":"7.1-f3","ref":"7.1","type":"fill","prompt":"Vacinas ____ são fundamentais conforme a doença e o contexto.","answers":[["essenciais","essencial"]],"explanation":"c) Vacinas essenciais são fundamentais conforme a doença e o contexto.","referenceAnswers":["essenciais"]},{"id":"7.1-f4","ref":"7.1","type":"fill","prompt":"Vacinas ____ dependem do estilo de vida, da região e da exposição.","answers":[["não essenciais","nao essenciais","não essencial","nao essencial"]],"explanation":"d) Vacinas não essenciais dependem do estilo de vida, da região e da exposição.","referenceAnswers":["não essenciais"]},{"id":"7.1-f5","ref":"7.1","type":"fill","prompt":"Vacinas ____ não apresentam evidências suficientes para justificar seu uso.","answers":[["não recomendadas","nao recomendadas","não recomendada","nao recomendada"]],"explanation":"e) Vacinas não recomendadas não apresentam evidências suficientes para justificar seu uso.","referenceAnswers":["não recomendadas"]},{"id":"7.2-match","ref":"7.2","type":"match","prompt":"Relacione cada descrição ao conceito correto.","labels":["Vivas modificadas (VVM)","Inativadas","Subunidades","Vetores","Ácidos nucleicos"],"pairs":[{"text":"Contêm componentes específicos do patógeno.","answer":"3"},{"text":"Utilizam DNA ou RNA; o texto descreve disponibilidade ainda limitada para cães e gatos.","answer":"5"},{"text":"Em geral, são imunogênicas e induzem imunidade duradoura.","answer":"1"},{"text":"Podem exigir múltiplas doses e adjuvantes.","answer":"2"},{"text":"Transportam material genético de outro patógeno.","answer":"4"}],"explanation":"Subunidades: Contêm componentes específicos do patógeno. | Ácidos nucleicos: Utilizam DNA ou RNA; o texto descreve disponibilidade ainda limitada para cães e gatos. | Vivas modificadas (VVM): Em geral, são imunogênicas e induzem imunidade duradoura. | Inativadas: Podem exigir múltiplas doses e adjuvantes. | Vetores: Transportam material genético de outro patógeno."},{"id":"7.3-a","ref":"7.3a","type":"choice","prompt":"O que significa duração da imunidade (DOI)?","context":"","options":["Período de proteção após a imunização","Tempo de fabricação do produto","Idade mínima para adoção","Intervalo entre sinais da doença"],"answer":"Período de proteção após a imunização","explanation":"DOI é o período durante o qual a imunização produz proteção contra a doença após a vacinação."},{"id":"7.3-b","ref":"7.3b","type":"choice","prompt":"Por que o protocolo deve considerar tanto o risco individual quanto o local?","context":"","options":["Exposição individual e ocorrência regional mudam a indicação","Todas as regiões apresentam o mesmo risco","Somente o tamanho do animal importa","Somente a cor da pelagem importa"],"answer":"Exposição individual e ocorrência regional mudam a indicação","explanation":"O estilo de vida, a exposição, a idade e o histórico do animal se combinam com a ocorrência regional de doenças para determinar a indicação das vacinas."},{"id":"7.3-c","ref":"7.3c","type":"choice","prompt":"Vacinas essenciais e não essenciais têm sempre a mesma frequência de reforço? Explique.","context":"","options":["Não; depende da DOI, do produto e do risco","Sim; todas devem ser mensais","Sim; todas devem ser trienais","Não; vacinas essenciais nunca precisam de reforço"],"answer":"Não; depende da DOI, do produto e do risco","explanation":"Não. Algumas vacinas virais essenciais induzem proteção prolongada, enquanto diversas outras exigem reforços mais frequentes. A decisão depende do produto, da DOI, do risco e das normas locais."}]},{"id":8,"title":"Vacinas caninas","group":"Vacinação","summary":["CDV, CAV e CPV-2 são os agentes virais essenciais globais.","CAV-2 vacinal protege contra CAV-1.","Raiva e leptospirose dependem do contexto local; não reduzir dose pelo porte."],"lesson":[{"type":"heading","text":"8.1 Complete a relação entre agente e doença."},{"type":"table","headers":["Agente","Doença ou associação"],"rows":[["CDV","Cinose canina"],["CAV-1","Hepatite infecciosa canina"],["CPV-2","Parvovirose canina"]]},{"type":"p","html":"<b>Atenção:</b> CAV-1 causa hepatite infecciosa; vacinas modernas contendo CAV-2 oferecem proteção cruzada contra CAV-1. [1]"},{"type":"heading","text":"8.2 Classifique conforme o contexto."},{"type":"qa","question":"a) Quais três agentes compõem o grupo viral essencial de distribuição global?","answer":"CDV, CAV e CPV-2. As vacinas modernas usam CAV-2 para proteger também contra a hepatite causada por CAV-1."},{"type":"qa","question":"b) Quando a vacinação contra leptospirose é considerada essencial?","answer":"Em regiões onde a leptospirose canina é endêmica e há vacinas adequadas aos sorogrupos envolvidos."},{"type":"qa","question":"c) Em que contexto a vacinação contra raiva é essencial, mesmo sem exigência legal?","answer":"Em áreas onde a raiva é endêmica, independentemente da existência de exigência legal."},{"type":"heading","text":"8.3 Vacinas não essenciais e não recomendadas"},{"type":"qa","question":"a) Cite três vacinas não essenciais mencionadas para cães.","answer":"Exemplos: parainfluenza, Bordetella bronchiseptica e influenza canina. Também são citadas leishmaniose e herpesvírus canino-1, conforme o contexto."},{"type":"qa","question":"b) Qual vacina pode ser considerada para cadelas gestantes?","answer":"A vacina contra herpesvírus canino-1, conforme a indicação do produto e o manejo reprodutivo."},{"type":"qa","question":"c) Cite duas vacinas não recomendadas no material, além da CPV-2 inativada.","answer":"Exemplos: coronavírus canino e Giardia spp. O material também cita Microsporum canis."},{"type":"qa","question":"d) Segundo o texto, por que a vacina contra Giardia não é recomendada?","answer":"Não há evidências suficientes de prevenção da infecção ou da eliminação do agente, e essas vacinas foram retiradas de muitos mercados."},{"type":"heading","text":"8.4 Influenza e dose em cães pequenos"},{"type":"p","html":"a) H3N8 teve origem em <b>cavalos</b>; H3N2 teve origem em <b>aves</b>."},{"type":"p","html":"b) O subtipo citado como capaz de ser transmitido de cães para gatos é <b>H3N2</b>."},{"type":"qa","question":"c) É correto aplicar meia dose ou um quarto da dose em cães pequenos? Justifique.","answer":"Não. Deve-se administrar a dose completa indicada pelo fabricante. A dose não deve ser reduzida apenas pelo porte; o texto associa a predisposição a eventos adversos também à raça."}],"questions":[{"id":"8.1-t1","ref":"8.1","type":"fill","prompt":"Qual doença está associada a CDV? ____","answers":[["Cinose canina","cinose"]],"explanation":"CDV: Cinose canina.","referenceAnswers":["Cinose canina"]},{"id":"8.1-t2","ref":"8.1","type":"fill","prompt":"Qual doença está associada a CAV-1? ____","answers":[["Hepatite infecciosa canina","hepatite infecciosa","hepatite canina"]],"explanation":"CAV-1: Hepatite infecciosa canina.","referenceAnswers":["Hepatite infecciosa canina"]},{"id":"8.1-t3","ref":"8.1","type":"fill","prompt":"Qual doença está associada a CPV-2? ____","answers":[["Parvovirose canina","parvovirose","parvovirose por cpv2"]],"explanation":"CPV-2: Parvovirose canina.","referenceAnswers":["Parvovirose canina"]},{"id":"8.2-a","ref":"8.2a","type":"choice","prompt":"Quais três agentes compõem o grupo viral essencial de distribuição global?","context":"","options":["CDV, CAV e CPV-2","FCV, FHV-1 e FPV","Giardia, coronavírus e Microsporum","FeLV, influenza e Chlamydia"],"answer":"CDV, CAV e CPV-2","explanation":"CDV, CAV e CPV-2. As vacinas modernas usam CAV-2 para proteger também contra a hepatite causada por CAV-1."},{"id":"8.2-b","ref":"8.2b","type":"choice","prompt":"Quando a vacinação contra leptospirose é considerada essencial?","context":"","options":["Endemia com vacinas adequadas aos sorogrupos envolvidos","Somente quando o cão apresenta doença ativa","Somente em gatos com acesso à rua","Nunca, mesmo em regiões endêmicas"],"answer":"Endemia com vacinas adequadas aos sorogrupos envolvidos","explanation":"Em regiões onde a leptospirose canina é endêmica e há vacinas adequadas aos sorogrupos envolvidos."},{"id":"8.2-c","ref":"8.2c","type":"choice","prompt":"Em que contexto a vacinação contra raiva é essencial, mesmo sem exigência legal?","context":"","options":["Em áreas endêmicas","Somente quando existe obrigação legal","Somente em animais infectados","Nunca em cães de abrigo"],"answer":"Em áreas endêmicas","explanation":"Em áreas onde a raiva é endêmica, independentemente da existência de exigência legal."},{"id":"8.3-a","ref":"8.3a","type":"choice","prompt":"Cite três vacinas não essenciais mencionadas para cães.","context":"","options":["Parainfluenza, Bordetella e influenza canina","Cinose, adenovírus e parvovirose","FPV, FCV e FHV-1","Coronavírus, Giardia e Microsporum"],"answer":"Parainfluenza, Bordetella e influenza canina","explanation":"Exemplos: parainfluenza, Bordetella bronchiseptica e influenza canina. Também são citadas leishmaniose e herpesvírus canino-1, conforme o contexto."},{"id":"8.3-b","ref":"8.3b","type":"choice","prompt":"Qual vacina pode ser considerada para cadelas gestantes?","context":"","options":["Herpesvírus canino-1","Herpesvírus felino-1","Panleucopenia felina","Giardia spp."],"answer":"Herpesvírus canino-1","explanation":"A vacina contra herpesvírus canino-1, conforme a indicação do produto e o manejo reprodutivo."},{"id":"8.3-c","ref":"8.3c","type":"choice","prompt":"Cite duas vacinas não recomendadas no material, além da CPV-2 inativada.","context":"","options":["Coronavírus canino e Giardia spp.","CDV e CPV-2 viva modificada","CAV-2 e cinose","Raiva em área endêmica e leptospirose indicada"],"answer":"Coronavírus canino e Giardia spp.","explanation":"Exemplos: coronavírus canino e Giardia spp. O material também cita Microsporum canis."},{"id":"8.3-d","ref":"8.3d","type":"choice","prompt":"Segundo o texto, por que a vacina contra Giardia não é recomendada?","context":"","options":["Evidência insuficiente de prevenção da infecção ou eliminação","Proteção comprovada de duração vitalícia","Indicação obrigatória em todos os cães","Recomendação como vacina essencial global"],"answer":"Evidência insuficiente de prevenção da infecção ou eliminação","explanation":"Não há evidências suficientes de prevenção da infecção ou da eliminação do agente, e essas vacinas foram retiradas de muitos mercados."},{"id":"8.4-f1","ref":"8.4","type":"fill","prompt":"H3N8 teve origem em ____; H3N2 teve origem em ____.","answers":[["cavalos","cavalo","equinos"],["aves","ave"]],"explanation":"a) H3N8 teve origem em cavalos; H3N2 teve origem em aves.","referenceAnswers":["cavalos","aves"]},{"id":"8.4-f3","ref":"8.4","type":"fill","prompt":"O subtipo citado como capaz de ser transmitido de cães para gatos é ____.","answers":[["H3N2"]],"explanation":"b) O subtipo citado como capaz de ser transmitido de cães para gatos é H3N2.","referenceAnswers":["H3N2"]},{"id":"8.4-c","ref":"8.4c","type":"choice","prompt":"É correto aplicar meia dose ou um quarto da dose em cães pequenos? Justifique.","context":"","options":["Não; usar a dose completa indicada","Sim; usar sempre metade da dose","Sim; usar sempre um quarto da dose","Sim; calcular a dose pela cor da pelagem"],"answer":"Não; usar a dose completa indicada","explanation":"Não. Deve-se administrar a dose completa indicada pelo fabricante. A dose não deve ser reduzida apenas pelo porte; o texto associa a predisposição a eventos adversos também à raça."}]},{"id":9,"title":"Vacinas felinas","group":"Vacinação","summary":["FPV, FHV-1 e FCV são essenciais.","FeLV depende da idade, da região e da exposição.","PIF é tratada como não recomendada; apresentações vacinais têm diferenças."],"lesson":[{"type":"heading","text":"9.1 Complete."},{"type":"p","html":"a) FPV está associado à <b>panleucopenia</b> felina."},{"type":"p","html":"b) FHV-1 está associado à <b>rinotraqueíte</b> viral felina."},{"type":"p","html":"c) O terceiro agente viral essencial, além de FPV e FHV-1, é o <b>calicivírus felino (FCV)</b>."},{"type":"p","html":"d) Em áreas endêmicas, a vacina contra <b>raiva</b> é essencial."},{"type":"heading","text":"9.2 FeLV: considere idade, exposição e região."},{"type":"p","html":"A classificação da FeLV depende do contexto. Em regiões em que a doença é endêmica ou relevante, é essencial para gatos jovens e adultos com exposição de risco. [1]"},{"type":"qa","question":"a) Qual faixa etária de gatos jovens é destacada no texto?","answer":"Gatos com menos de 1 ano, no contexto regional de ocorrência relevante de FeLV."},{"type":"qa","question":"b) Que característica de um gato adulto aumenta a indicação da vacina?","answer":"Acesso à rua ou convivência com gatos que têm acesso externo, por aumentar o risco de exposição."},{"type":"heading","text":"9.3 Relacione as apresentações."},{"type":"p","html":"<b>(1) Parenteral viva atenuada<br/>(2) Parenteral inativada<br/>(3) Intranasal viva atenuada</b>"},{"type":"p","html":"<b>(3)</b> Pode conferir proteção rápida contra FHV e FCV, mas é menos eficaz contra FPV."},{"type":"p","html":"<b>(1)</b> É contraindicada para gatas gestantes e filhotes menores de 4 semanas."},{"type":"p","html":"<b>(2)</b> Geralmente apresenta início de proteção menos rápido; pode ser preferida na gestação."},{"type":"heading","text":"9.4 Indicações específicas"},{"type":"qa","question":"a) Em que situação considerar Chlamydia felis? A proteção é completa?","answer":"Em ambientes com múltiplos gatos e infecção confirmada por Chlamydia felis. A proteção é incompleta."},{"type":"qa","question":"b) Bordetella bronchiseptica deve ser usada rotineiramente em gatos de estimação?","answer":"Não. Pode ser considerada em colônias grandes ou outras situações específicas de risco."},{"type":"p","html":"<b>Nota de revisão:</b> PIF/FIP aparece em duas categorias no texto original. Neste guia, é tratada como não recomendada, por evidência insuficiente de proteção relevante. [1]"},{"type":"qa","question":"c) Quais outras duas vacinas felinas não recomendadas são citadas?","answer":"Giardia spp. e Microsporum canis."}],"questions":[{"id":"9.1-f1","ref":"9.1","type":"fill","prompt":"FPV está associado à ____ felina.","answers":[["panleucopenia","panleucopenia felina"]],"explanation":"a) FPV está associado à panleucopenia felina.","referenceAnswers":["panleucopenia"]},{"id":"9.1-f2","ref":"9.1","type":"fill","prompt":"FHV-1 está associado à ____ viral felina.","answers":[["rinotraqueíte","rinotraqueite","rinotraqueite felina"]],"explanation":"b) FHV-1 está associado à rinotraqueíte viral felina.","referenceAnswers":["rinotraqueíte"]},{"id":"9.1-f3","ref":"9.1","type":"fill","prompt":"O terceiro agente viral essencial, além de FPV e FHV-1, é o ____.","answers":[["calicivírus felino (FCV)","FCV","calicivirus felino","calicivírus"]],"explanation":"c) O terceiro agente viral essencial, além de FPV e FHV-1, é o calicivírus felino (FCV).","referenceAnswers":["calicivírus felino (FCV)"]},{"id":"9.1-f4","ref":"9.1","type":"fill","prompt":"Em áreas endêmicas, a vacina contra ____ é essencial.","answers":[["raiva"]],"explanation":"d) Em áreas endêmicas, a vacina contra raiva é essencial.","referenceAnswers":["raiva"]},{"id":"9.2-a","ref":"9.2a","type":"choice","prompt":"Qual faixa etária de gatos jovens é destacada no texto?","context":"","options":["Menos de 1 ano","Somente mais de 10 anos","Somente 2 a 5 anos","Somente mais de 16 anos"],"answer":"Menos de 1 ano","explanation":"Gatos com menos de 1 ano, no contexto regional de ocorrência relevante de FeLV."},{"id":"9.2-b","ref":"9.2b","type":"choice","prompt":"Que característica de um gato adulto aumenta a indicação da vacina?","context":"","options":["Acesso à rua ou contato com gatos de acesso externo","Somente pelagem longa","Somente ser castrado","Somente dormir durante o dia"],"answer":"Acesso à rua ou contato com gatos de acesso externo","explanation":"Acesso à rua ou convivência com gatos que têm acesso externo, por aumentar o risco de exposição."},{"id":"9.3-match","ref":"9.3","type":"match","prompt":"Relacione cada descrição ao conceito correto.","labels":["Parenteral viva atenuada","Parenteral inativada","Intranasal viva atenuada"],"pairs":[{"text":"Pode conferir proteção rápida contra FHV e FCV, mas é menos eficaz contra FPV.","answer":"3"},{"text":"É contraindicada para gatas gestantes e filhotes menores de 4 semanas.","answer":"1"},{"text":"Geralmente apresenta início de proteção menos rápido; pode ser preferida na gestação.","answer":"2"}],"explanation":"Intranasal viva atenuada: Pode conferir proteção rápida contra FHV e FCV, mas é menos eficaz contra FPV. | Parenteral viva atenuada: É contraindicada para gatas gestantes e filhotes menores de 4 semanas. | Parenteral inativada: Geralmente apresenta início de proteção menos rápido; pode ser preferida na gestação."},{"id":"9.4-a","ref":"9.4a","type":"choice","prompt":"Em que situação considerar Chlamydia felis? A proteção é completa?","context":"","options":["Múltiplos gatos com infecção confirmada; proteção incompleta","Todos os gatos; proteção sempre completa","Somente cães; proteção vitalícia","Nunca em grupos com infecção confirmada"],"answer":"Múltiplos gatos com infecção confirmada; proteção incompleta","explanation":"Em ambientes com múltiplos gatos e infecção confirmada por Chlamydia felis. A proteção é incompleta."},{"id":"9.4-b","ref":"9.4b","type":"choice","prompt":"Bordetella bronchiseptica deve ser usada rotineiramente em gatos de estimação?","context":"","options":["Não; considerar em colônias grandes ou risco específico","Sim; para todos os gatos, sem avaliar risco","Sim; substitui FPV, FCV e FHV-1","Não; é sempre contraindicado em colônias"],"answer":"Não; considerar em colônias grandes ou risco específico","explanation":"Não. Pode ser considerada em colônias grandes ou outras situações específicas de risco."},{"id":"9.4-c","ref":"9.4c","type":"choice","prompt":"Quais outras duas vacinas felinas não recomendadas são citadas?","context":"","options":["Giardia spp. e Microsporum canis","FPV e FCV","FHV-1 e raiva em área endêmica","FPV e FeLV quando indicada"],"answer":"Giardia spp. e Microsporum canis","explanation":"Giardia spp. e Microsporum canis."}]},{"id":10,"title":"Anticorpos maternos e esquemas de vacinação","group":"Vacinação","summary":["MDA podem proteger e também interferir na vacinação.","Série de rotina: início entre 6 e 8 semanas; última dose com 16 semanas ou mais.","Alto risco e ambiente de abrigo exigem atenção a protocolos específicos."],"lesson":[{"type":"heading","text":"10.1 Complete."},{"type":"p","html":"a) Os anticorpos maternos são abreviados como <b>MDA</b>."},{"type":"p","html":"b) Eles podem proteger o filhote, mas também <b>interferir</b> na resposta à vacina."},{"type":"p","html":"c) A vacinação de rotina dos filhotes começa entre <b>6 a 8</b> semanas."},{"type":"p","html":"d) O intervalo geral entre doses essenciais é de <b>2 a 4</b> semanas."},{"type":"p","html":"e) A última dose da série primária deve ocorrer a partir de <b>16</b> semanas."},{"type":"p","html":"f) Em alto risco, o texto recomenda concluir entre <b>18 e 20</b> semanas."},{"type":"p","html":"g) Se for possível apenas uma dose essencial, ela deve ocorrer com <b>16</b> semanas ou mais."},{"type":"heading","text":"10.2 Organize o planejamento."},{"type":"p","html":"A revacinação descrita como \"aos 6 meses\" corresponde à recomendação de uma dose em torno de 26 semanas ou depois. A confirmação sorológica de proteção pode orientar essa decisão. [1]"},{"type":"qa","question":"a) Por que contar doses, sem considerar a idade da última, não é suficiente?","answer":"Porque os MDA podem bloquear doses aplicadas cedo. É necessário que pelo menos uma dose seja administrada em idade na qual essa interferência seja menor; por isso a última dose não deve ser anterior a 16 semanas."},{"type":"qa","question":"b) Em cães adultos adequadamente imunizados, qual intervalo geral é usado para CDV/CAV/CPV-2?","answer":"Em geral, a cada 3 anos para essas vacinas virais essenciais, após imunização adequada."},{"type":"qa","question":"c) Por que raiva e leptospirose não devem ser colocadas automaticamente nesse mesmo intervalo?","answer":"A duração da proteção, a bula, o risco e as exigências locais podem demandar outros intervalos. O intervalo trienal não se aplica automaticamente a todas as vacinas."},{"type":"qa","question":"d) Para gatos com mais de 16 semanas, quantas doses e qual intervalo o texto descreve em geral?","answer":"Em geral, 2 doses, com 2 a 4 semanas de intervalo, conforme o esquema descrito no texto; a tecnologia e a bula precisam ser consideradas."},{"type":"qa","question":"e) Como o risco de um gato adulto interfere na frequência dos reforços?","answer":"No material, gatos de baixo risco podem receber reforços trienais das vacinas essenciais; os de alto risco podem precisar de maior frequência, especialmente contra FHV e FCV, até anual. Isso não implica aplicar anualmente todas as vacinas."},{"type":"heading","text":"10.3 Situação-problema"},{"type":"p","html":"Um filhote recebeu doses às 6, 10 e 14 semanas, mas o tutor considera o esquema encerrado."},{"type":"qa","question":"Qual ponto do cronograma precisa ser revisto e qual a relação com os MDA?","answer":"O esquema terminou antes de 16 semanas. Deve-se planejar uma dose com 16 semanas ou mais, podendo prolongar até 18 a 20 semanas em alto risco. Doses anteriores podem ter sido bloqueadas pelos MDA. O texto também prevê revacinação por volta de 26 semanas ou avaliação sorológica de proteção."}],"questions":[{"id":"10.1-f1","ref":"10.1","type":"fill","prompt":"Os anticorpos maternos são abreviados como ____.","answers":[["MDA","MDAs","anticorpos maternos"]],"explanation":"a) Os anticorpos maternos são abreviados como MDA.","referenceAnswers":["MDA"]},{"id":"10.1-f2","ref":"10.1","type":"fill","prompt":"Eles podem proteger o filhote, mas também ____ na resposta à vacina.","answers":[["interferir","bloquear"]],"explanation":"b) Eles podem proteger o filhote, mas também interferir na resposta à vacina.","referenceAnswers":["interferir"]},{"id":"10.1-f3","ref":"10.1","type":"fill","prompt":"A vacinação de rotina dos filhotes começa entre ____ semanas.","answers":[["6 a 8"]],"explanation":"c) A vacinação de rotina dos filhotes começa entre 6 a 8 semanas.","referenceAnswers":["6 a 8"]},{"id":"10.1-f4","ref":"10.1","type":"fill","prompt":"O intervalo geral entre doses essenciais é de ____ semanas.","answers":[["2 a 4"]],"explanation":"d) O intervalo geral entre doses essenciais é de 2 a 4 semanas.","referenceAnswers":["2 a 4"]},{"id":"10.1-f5","ref":"10.1","type":"fill","prompt":"A última dose da série primária deve ocorrer a partir de ____ semanas.","answers":[["16"]],"explanation":"e) A última dose da série primária deve ocorrer a partir de 16 semanas.","referenceAnswers":["16"]},{"id":"10.1-f6","ref":"10.1","type":"fill","prompt":"Em alto risco, o texto recomenda concluir entre ____ semanas.","answers":[["18 e 20"]],"explanation":"f) Em alto risco, o texto recomenda concluir entre 18 e 20 semanas.","referenceAnswers":["18 e 20"]},{"id":"10.1-f7","ref":"10.1","type":"fill","prompt":"Se for possível apenas uma dose essencial, ela deve ocorrer com ____ semanas ou mais.","answers":[["16"]],"explanation":"g) Se for possível apenas uma dose essencial, ela deve ocorrer com 16 semanas ou mais.","referenceAnswers":["16"]},{"id":"10.2-a","ref":"10.2a","type":"choice","prompt":"Por que contar doses, sem considerar a idade da última, não é suficiente?","context":"","options":["MDA podem bloquear doses precoces; a idade final importa","Todas as doses são eficazes independentemente da idade","Somente o número do lote define proteção","MDA sempre tornam desnecessária a série primária"],"answer":"MDA podem bloquear doses precoces; a idade final importa","explanation":"Porque os MDA podem bloquear doses aplicadas cedo. É necessário que pelo menos uma dose seja administrada em idade na qual essa interferência seja menor; por isso a última dose não deve ser anterior a 16 semanas."},{"id":"10.2-b","ref":"10.2b","type":"choice","prompt":"Em cães adultos adequadamente imunizados, qual intervalo geral é usado para CDV/CAV/CPV-2?","context":"","options":["Em geral, a cada 3 anos","Todas as semanas","Todos os meses","Nunca após a primeira dose"],"answer":"Em geral, a cada 3 anos","explanation":"Em geral, a cada 3 anos para essas vacinas virais essenciais, após imunização adequada."},{"id":"10.2-c","ref":"10.2c","type":"choice","prompt":"Por que raiva e leptospirose não devem ser colocadas automaticamente nesse mesmo intervalo?","context":"","options":["DOI, bula, risco e exigências locais podem ser diferentes","Toda vacina tem proteção idêntica","Raiva e leptospirose não precisam de reforço","Essas vacinas devem ser aplicadas só na gestação"],"answer":"DOI, bula, risco e exigências locais podem ser diferentes","explanation":"A duração da proteção, a bula, o risco e as exigências locais podem demandar outros intervalos. O intervalo trienal não se aplica automaticamente a todas as vacinas."},{"id":"10.2-d","ref":"10.2d","type":"choice","prompt":"Para gatos com mais de 16 semanas, quantas doses e qual intervalo o texto descreve em geral?","context":"","options":["Em geral, 2 doses com 2 a 4 semanas de intervalo","Uma dose diária por 7 dias","Sempre 4 doses em um único dia","Sempre uma dose com intervalo de 10 anos"],"answer":"Em geral, 2 doses com 2 a 4 semanas de intervalo","explanation":"Em geral, 2 doses, com 2 a 4 semanas de intervalo, conforme o esquema descrito no texto; a tecnologia e a bula precisam ser consideradas."},{"id":"10.2-e","ref":"10.2e","type":"choice","prompt":"Como o risco de um gato adulto interfere na frequência dos reforços?","context":"","options":["Maior risco pode exigir reforços mais frequentes, sobretudo FHV/FCV","Todos os gatos devem receber todas as vacinas mensalmente","Gatos de alto risco dispensam reforços","FPV, FHV e FCV sempre têm o mesmo intervalo em todo contexto"],"answer":"Maior risco pode exigir reforços mais frequentes, sobretudo FHV/FCV","explanation":"No material, gatos de baixo risco podem receber reforços trienais das vacinas essenciais; os de alto risco podem precisar de maior frequência, especialmente contra FHV e FCV, até anual. Isso não implica aplicar anualmente todas as vacinas."},{"id":"10.3-1","ref":"10.31","type":"choice","prompt":"Qual ponto do cronograma precisa ser revisto e qual a relação com os MDA?","context":"Um filhote recebeu doses às 6, 10 e 14 semanas, mas o tutor considera o esquema encerrado.","options":["Falta uma dose com 16 semanas ou mais, por causa dos MDA","Está encerrado; três doses garantem proteção em qualquer idade","É preciso reduzir todas as doses pela metade","É preciso suspender a vacinação até 5 anos"],"answer":"Falta uma dose com 16 semanas ou mais, por causa dos MDA","explanation":"O esquema terminou antes de 16 semanas. Deve-se planejar uma dose com 16 semanas ou mais, podendo prolongar até 18 a 20 semanas em alto risco. Doses anteriores podem ter sido bloqueadas pelos MDA. O texto também prevê revacinação por volta de 26 semanas ou avaliação sorológica de proteção."}]},{"id":11,"title":"Sorologia e falhas de imunização","group":"Vacinação","summary":["Sorologia: a partir de 20 semanas e ao menos 4 semanas após a última dose.","Anticorpos contra CDV/CAV/CPV e FPV são os marcadores destacados.","Resultado negativo não avalia toda a memória; investigar a janela de suscetibilidade."],"lesson":[{"type":"heading","text":"11.1 Complete os critérios do teste pós-vacinal."},{"type":"p","html":"a) A avaliação é indicada a partir de <b>20</b> semanas de idade."},{"type":"p","html":"b) Deve-se respeitar pelo menos <b>4</b> semanas após a última dose primária."},{"type":"p","html":"c) Os agentes avaliados em cães incluem <b>CDV</b>, <b>CAV</b> e <b>CPV</b>."},{"type":"p","html":"d) Em gatos, o marcador de proteção destacado é contra <b>FPV</b>."},{"type":"heading","text":"11.2 Responda."},{"type":"qa","question":"a) O que um resultado positivo geralmente indica nesse contexto?","answer":"Em animais com idade e momento de coleta adequados, anticorpos contra CDV/CAV/CPV em cães e FPV em gatos geralmente indicam proteção robusta."},{"type":"qa","question":"b) Qual conduta deve ser considerada diante de um resultado negativo?","answer":"Considerar revacinação e reavaliação sorológica. Um resultado negativo não prova ausência completa de proteção, pois o teste não avalia toda a memória e a imunidade celular. [1]"},{"type":"qa","question":"c) Por que é necessário cautela com testes rápidos e resultados discordantes?","answer":"A sensibilidade e a especificidade variam, podendo ocorrer falsos positivos e negativos. Resultados discordantes podem exigir confirmação por teste laboratorial de referência."},{"type":"qa","question":"d) Qual teste rápido canino é citado como geralmente mais confiável?","answer":"O teste para anticorpos contra CPV, segundo o texto."},{"type":"heading","text":"11.3 Janela de suscetibilidade"},{"type":"p","html":"Complete: os MDA podem estar baixos demais para <b>proteger</b> contra o vírus de campo, mas ainda altos o suficiente para <b>bloquear</b> a resposta à vacina."},{"type":"heading","text":"11.4 Situação-problema"},{"type":"p","html":"Um filhote adoece poucos dias após ser vacinado. O tutor conclui que qualquer doença após a aplicação prova falha da vacina."},{"type":"qa","question":"a) Qual hipótese envolve a incubação da doença?","answer":"O animal já podia estar incubando a doença antes de receber a vacina, que não trata uma infecção em curso."},{"type":"qa","question":"b) Qual hipótese envolve os anticorpos maternos?","answer":"A infecção pode ter ocorrido na janela de suscetibilidade: MDA insuficientes para proteger, mas ainda capazes de interferir na vacinação."},{"type":"qa","question":"c) Em um canil, quais fatores de manejo devem ser avaliados junto ao cronograma e à imunização das reprodutoras?","answer":"Higiene, nutrição, superlotação, estresse, condições de criação e imunização das reprodutoras, que influencia a proteção passiva dos filhotes."}],"questions":[{"id":"11.1-f1","ref":"11.1","type":"fill","prompt":"A avaliação é indicada a partir de ____ semanas de idade.","answers":[["20"]],"explanation":"a) A avaliação é indicada a partir de 20 semanas de idade.","referenceAnswers":["20"]},{"id":"11.1-f2","ref":"11.1","type":"fill","prompt":"Deve-se respeitar pelo menos ____ semanas após a última dose primária.","answers":[["4"]],"explanation":"b) Deve-se respeitar pelo menos 4 semanas após a última dose primária.","referenceAnswers":["4"]},{"id":"11.1-f3","ref":"11.1","type":"fill","prompt":"Os agentes avaliados em cães incluem ____, ____ e ____.","answers":[["CDV","CAV","CPV","CPV-2","CPV2"],["CDV","CAV","CPV","CPV-2","CPV2"],["CDV","CAV","CPV","CPV-2","CPV2"]],"explanation":"c) Os agentes avaliados em cães incluem CDV, CAV e CPV.","referenceAnswers":["CDV","CAV","CPV"],"distinct":true,"distinctGroups":[["CDV"],["CAV"],["CPV","CPV-2","CPV2"]]},{"id":"11.1-f6","ref":"11.1","type":"fill","prompt":"Em gatos, o marcador de proteção destacado é contra ____.","answers":[["FPV"]],"explanation":"d) Em gatos, o marcador de proteção destacado é contra FPV.","referenceAnswers":["FPV"]},{"id":"11.2-a","ref":"11.2a","type":"choice","prompt":"O que um resultado positivo geralmente indica nesse contexto?","context":"","options":["Geralmente indica proteção para os agentes avaliados","Comprova qualquer infecção ativa","Indica ausência de toda memória","Indica contraindicação definitiva a qualquer vacina"],"answer":"Geralmente indica proteção para os agentes avaliados","explanation":"Em animais com idade e momento de coleta adequados, anticorpos contra CDV/CAV/CPV em cães e FPV em gatos geralmente indicam proteção robusta."},{"id":"11.2-b","ref":"11.2b","type":"choice","prompt":"Qual conduta deve ser considerada diante de um resultado negativo?","context":"","options":["Considerar revacinação e reavaliação sorológica","Concluir que nunca houve memória imunológica","Dispensar toda investigação e toda revacinação","Aplicar meia dose como regra universal"],"answer":"Considerar revacinação e reavaliação sorológica","explanation":"Considerar revacinação e reavaliação sorológica. Um resultado negativo não prova ausência completa de proteção, pois o teste não avalia toda a memória e a imunidade celular. [1]"},{"id":"11.2-c","ref":"11.2c","type":"choice","prompt":"Por que é necessário cautela com testes rápidos e resultados discordantes?","context":"","options":["Podem ocorrer falsos positivos e negativos","Todos têm sensibilidade e especificidade perfeitas","Qualquer resultado rápido dispensa contexto","Um resultado negativo sempre comprova doença ativa"],"answer":"Podem ocorrer falsos positivos e negativos","explanation":"A sensibilidade e a especificidade variam, podendo ocorrer falsos positivos e negativos. Resultados discordantes podem exigir confirmação por teste laboratorial de referência."},{"id":"11.2-d","ref":"11.2d","type":"choice","prompt":"Qual teste rápido canino é citado como geralmente mais confiável?","context":"","options":["Anticorpos contra CPV","Anticorpos contra Giardia","Anticorpos contra Microsporum","IgE contra alimentos"],"answer":"Anticorpos contra CPV","explanation":"O teste para anticorpos contra CPV, segundo o texto."},{"id":"11.3-f1","ref":"11.3","type":"fill","prompt":"Complete: os MDA podem estar baixos demais para ____ contra o vírus de campo, mas ainda altos o suficiente para ____ a resposta à vacina.","answers":[["proteger","protecao"],["bloquear","interferir","interferir na"]],"explanation":"Complete: os MDA podem estar baixos demais para proteger contra o vírus de campo, mas ainda altos o suficiente para bloquear a resposta à vacina.","referenceAnswers":["proteger","bloquear"]},{"id":"11.4-a","ref":"11.4a","type":"choice","prompt":"Qual hipótese envolve a incubação da doença?","context":"Um filhote adoece poucos dias após ser vacinado. O tutor conclui que qualquer doença após a aplicação prova falha da vacina.","options":["A doença já estava incubando antes da vacina","A vacina trata qualquer infecção já instalada","A incubação começa apenas após a revacinação","Toda doença posterior é necessariamente causada pela vacina"],"answer":"A doença já estava incubando antes da vacina","explanation":"O animal já podia estar incubando a doença antes de receber a vacina, que não trata uma infecção em curso."},{"id":"11.4-b","ref":"11.4b","type":"choice","prompt":"Qual hipótese envolve os anticorpos maternos?","context":"Um filhote adoece poucos dias após ser vacinado. O tutor conclui que qualquer doença após a aplicação prova falha da vacina.","options":["MDA baixos para proteger, mas suficientes para interferir","MDA sempre ausentes desde o nascimento","MDA sempre impedem a infecção e a vacinação","MDA afetam apenas a nutrição"],"answer":"MDA baixos para proteger, mas suficientes para interferir","explanation":"A infecção pode ter ocorrido na janela de suscetibilidade: MDA insuficientes para proteger, mas ainda capazes de interferir na vacinação."},{"id":"11.4-c","ref":"11.4c","type":"choice","prompt":"Em um canil, quais fatores de manejo devem ser avaliados junto ao cronograma e à imunização das reprodutoras?","context":"Um filhote adoece poucos dias após ser vacinado. O tutor conclui que qualquer doença após a aplicação prova falha da vacina.","options":["Higiene, nutrição, lotação, estresse e manejo das reprodutoras","Somente a cor do canil","Somente o nome comercial da ração","Somente o porte do filhote"],"answer":"Higiene, nutrição, lotação, estresse e manejo das reprodutoras","explanation":"Higiene, nutrição, superlotação, estresse, condições de criação e imunização das reprodutoras, que influencia a proteção passiva dos filhotes."}]},{"id":12,"title":"Abrigos, reprodutoras e uso em outras espécies","group":"Vacinação","summary":["Abrigos: vacinação na entrada e séries específicas para filhotes.","Preferir vacinar reprodutoras antes da gestação.","Uso fora da bula requer segurança, risco-benefício e consentimento documentado."],"lesson":[{"type":"heading","text":"12.1 Vacinação em abrigos e santuários"},{"type":"p","html":"a) Os animais devem receber vacinas essenciais na <b>entrada</b> do abrigo."},{"type":"p","html":"b) Nesse ambiente, a série dos filhotes pode começar com <b>4</b> semanas."},{"type":"p","html":"c) As doses são repetidas a cada <b>2 a 3</b> semanas até <b>5</b> meses."},{"type":"p","html":"d) Em cães de abrigo, vacinas contra doenças <b>respiratórias</b> são consideradas essenciais."},{"type":"qa","question":"e) Quais três agentes compõem a vacinação essencial felina no abrigo?","answer":"FPV, FHV-1 e FCV; raiva também é essencial em áreas endêmicas."},{"type":"qa","question":"f) Que fatores orientam o uso de FeLV, Bordetella e Chlamydia em grupos de gatos?","answer":"Para FeLV, avaliar idade, região e exposição em grupo. Para Bordetella e Chlamydia, considerar o tamanho do grupo, o risco e a confirmação de infecção; seu uso não é automaticamente rotineiro."},{"type":"heading","text":"12.2 Cadelas e gatas reprodutoras"},{"type":"qa","question":"a) Qual é o momento preferencial para vacinar em relação à gestação?","answer":"Antes da gestação, evitando a vacinação durante a gestação quando possível."},{"type":"qa","question":"b) Se a vacinação na gestação for necessária, qual tecnologia é preferida?","answer":"Vacinas inativadas, quando necessárias e apropriadas à indicação."},{"type":"qa","question":"c) O que deve ser verificado antes de usar VVM em uma gestante?","answer":"Se o fabricante aprova aquela vacina para uso em gestantes, além da avaliação de risco-benefício."},{"type":"qa","question":"d) Qual é o objetivo de considerar reforços em cadelas reprodutoras para aumentar a proteção passiva dos filhotes?","answer":"Aumentar os anticorpos no colostro e, assim, a proteção passiva dos filhotes. O texto apresenta essa possibilidade para cadelas reprodutoras; não é uma regra de reforço anual para todos os animais."},{"type":"heading","text":"12.3 Espécies não licenciadas e uso fora da bula"},{"type":"qa","question":"a) Quais riscos podem ocorrer ao usar uma vacina em espécie não licenciada?","answer":"Doença e morte, além de risco de disseminação e recuperação de virulência, especialmente com certos agentes vacinais em espécies suscetíveis."},{"type":"qa","question":"b) Qual tecnologia é citada como possível exceção sob avaliação de risco-benefício?","answer":"Vacinas recombinantes, como as com vetor canarypox contra CDV, após avaliação de segurança e de risco-benefício."},{"type":"qa","question":"c) O que significa uso \"off-label\" e qual consentimento deve ser documentado?","answer":"Uso fora das condições aprovadas em bula, como espécie ou indicação. Deve-se documentar o consentimento informado do responsável."}],"questions":[{"id":"12.1-f1","ref":"12.1","type":"fill","prompt":"Os animais devem receber vacinas essenciais na ____ do abrigo.","answers":[["entrada","admissão","admissao"]],"explanation":"a) Os animais devem receber vacinas essenciais na entrada do abrigo.","referenceAnswers":["entrada"]},{"id":"12.1-f2","ref":"12.1","type":"fill","prompt":"Nesse ambiente, a série dos filhotes pode começar com ____ semanas.","answers":[["4"]],"explanation":"b) Nesse ambiente, a série dos filhotes pode começar com 4 semanas.","referenceAnswers":["4"]},{"id":"12.1-f3","ref":"12.1","type":"fill","prompt":"As doses são repetidas a cada ____ semanas até ____ meses.","answers":[["2 a 3"],["5"]],"explanation":"c) As doses são repetidas a cada 2 a 3 semanas até 5 meses.","referenceAnswers":["2 a 3","5"]},{"id":"12.1-f5","ref":"12.1","type":"fill","prompt":"Em cães de abrigo, vacinas contra doenças ____ são consideradas essenciais.","answers":[["respiratórias","respiratorias","respiratoria"]],"explanation":"d) Em cães de abrigo, vacinas contra doenças respiratórias são consideradas essenciais.","referenceAnswers":["respiratórias"]},{"id":"12.1-e","ref":"12.1e","type":"choice","prompt":"Quais três agentes compõem a vacinação essencial felina no abrigo?","context":"","options":["FPV, FHV-1 e FCV","CDV, CAV e CPV-2","Giardia, Microsporum e PIF","Influenza, herpesvírus canino e cinose"],"answer":"FPV, FHV-1 e FCV","explanation":"FPV, FHV-1 e FCV; raiva também é essencial em áreas endêmicas."},{"id":"12.1-f","ref":"12.1f","type":"choice","prompt":"Que fatores orientam o uso de FeLV, Bordetella e Chlamydia em grupos de gatos?","context":"","options":["Idade, região, exposição, tamanho do grupo e infecção confirmada","Aplicar todas automaticamente em qualquer gato","Somente o peso do gato","Somente a estação do ano"],"answer":"Idade, região, exposição, tamanho do grupo e infecção confirmada","explanation":"Para FeLV, avaliar idade, região e exposição em grupo. Para Bordetella e Chlamydia, considerar o tamanho do grupo, o risco e a confirmação de infecção; seu uso não é automaticamente rotineiro."},{"id":"12.2-a","ref":"12.2a","type":"choice","prompt":"Qual é o momento preferencial para vacinar em relação à gestação?","context":"","options":["Antes da gestação","Sempre durante o parto","Somente depois da primeira mamada","Obrigatoriamente no fim de toda gestação"],"answer":"Antes da gestação","explanation":"Antes da gestação, evitando a vacinação durante a gestação quando possível."},{"id":"12.2-b","ref":"12.2b","type":"choice","prompt":"Se a vacinação na gestação for necessária, qual tecnologia é preferida?","context":"","options":["Inativada, quando indicada","Sempre viva atenuada, sem consultar a bula","Somente intranasal, em toda situação","Nosódios, como substitutos obrigatórios"],"answer":"Inativada, quando indicada","explanation":"Vacinas inativadas, quando necessárias e apropriadas à indicação."},{"id":"12.2-c","ref":"12.2c","type":"choice","prompt":"O que deve ser verificado antes de usar VVM em uma gestante?","context":"","options":["Aprovação do fabricante para gestantes e risco-benefício","Somente a cor do frasco","Somente o preço do produto","Apenas o tamanho da ninhada"],"answer":"Aprovação do fabricante para gestantes e risco-benefício","explanation":"Se o fabricante aprova aquela vacina para uso em gestantes, além da avaliação de risco-benefício."},{"id":"12.2-d","ref":"12.2d","type":"choice","prompt":"Qual é o objetivo de considerar reforços em cadelas reprodutoras para aumentar a proteção passiva dos filhotes?","context":"","options":["Aumentar anticorpos no colostro e proteção passiva","Eliminar definitivamente todos os MDA","Produzir imunidade ativa fetal por qualquer vacina","Dispensar a vacinação dos filhotes para sempre"],"answer":"Aumentar anticorpos no colostro e proteção passiva","explanation":"Aumentar os anticorpos no colostro e, assim, a proteção passiva dos filhotes. O texto apresenta essa possibilidade para cadelas reprodutoras; não é uma regra de reforço anual para todos os animais."},{"id":"12.3-a","ref":"12.3a","type":"choice","prompt":"Quais riscos podem ocorrer ao usar uma vacina em espécie não licenciada?","context":"","options":["Doença, morte, disseminação e recuperação de virulência","Ausência garantida de qualquer risco","Proteção universal em toda espécie","Somente mudança da cor da pelagem"],"answer":"Doença, morte, disseminação e recuperação de virulência","explanation":"Doença e morte, além de risco de disseminação e recuperação de virulência, especialmente com certos agentes vacinais em espécies suscetíveis."},{"id":"12.3-b","ref":"12.3b","type":"choice","prompt":"Qual tecnologia é citada como possível exceção sob avaliação de risco-benefício?","context":"","options":["Recombinante, como canarypox contra CDV","Qualquer VVM, sem avaliar segurança","Qualquer vacina inativada, em qualquer espécie","Nosódios homeopáticos"],"answer":"Recombinante, como canarypox contra CDV","explanation":"Vacinas recombinantes, como as com vetor canarypox contra CDV, após avaliação de segurança e de risco-benefício."},{"id":"12.3-c","ref":"12.3c","type":"choice","prompt":"O que significa uso \"off-label\" e qual consentimento deve ser documentado?","context":"","options":["Uso fora da bula, com consentimento informado documentado","Aplicação conforme a bula, sem registro","Uso de lote vencido como regra","Aplicação de qualquer vacina sem responsável"],"answer":"Uso fora da bula, com consentimento informado documentado","explanation":"Uso fora das condições aprovadas em bula, como espécie ou indicação. Deve-se documentar o consentimento informado do responsável."}]},{"id":13,"title":"Eventos adversos e documentação","group":"Vacinação","summary":["Notificar eventos suspeitos ao fabricante e às autoridades.","Massas: investigar se >2 cm, persistirem 3 meses ou crescerem após 1 mês.","Registrar data, produto, lote, fabricante, via e local."],"lesson":[{"type":"heading","text":"13.1 Relacione os tipos de eventos pós-vacinação."},{"type":"p","html":"<b>(1) Reações locais<br/>(2) Reações sistêmicas menores<br/>(3) Eventos raros</b>"},{"type":"p","html":"<b>(2)</b> Letargia, anorexia, febre e vômito."},{"type":"p","html":"<b>(1)</b> Dor e inchaço."},{"type":"p","html":"<b>(3)</b> Urticária, anafilaxia e sarcoma de sítio de injeção felino."},{"type":"qa","question":"Por que um evento que ocorre após a vacina não comprova, por si só, relação causal?","answer":"Porque a sequência temporal não demonstra causalidade. O evento pode estar relacionado à aplicação ou ter outra causa; é necessário investigar e registrar."},{"type":"heading","text":"13.2 Sarcoma de sítio de injeção felino (SSIF)"},{"type":"qa","question":"a) Que região anatômica é recomendada no texto para a aplicação?","answer":"Regiões distais dos membros; o texto destaca as patas traseiras."},{"type":"qa","question":"b) Por que o local de cada injeção deve ser registrado?","answer":"Para relacionar uma eventual massa ao local aplicado, acompanhar eventos e facilitar o planejamento diagnóstico e terapêutico."},{"type":"p","html":"Complete os critérios para investigar uma massa no local da aplicação:"},{"type":"p","html":"• Diâmetro maior que <b>2</b> cm."},{"type":"p","html":"• Persistência por <b>3</b> meses."},{"type":"p","html":"• Aumento de tamanho após <b>1</b> mês."},{"type":"qa","question":"c) Qual procedimento diagnóstico é indicado quando um desses critérios ocorre?","answer":"Biópsia da massa quando ocorrer qualquer um dos critérios da regra 3-2-1."},{"type":"heading","text":"13.3 Notificação e registros"},{"type":"qa","question":"a) A quem o veterinário deve notificar os eventos adversos suspeitos?","answer":"Ao fabricante e às autoridades reguladoras."},{"type":"p","html":"Preencha os campos que um registro vacinal deve conter:"},{"type":"table","headers":["Campo","Informação a registrar"],"rows":[["Data","Dia, mês e ano da vacinação"],["Identificação do produto","Nome da vacina e número do lote"],["Origem","Fabricante do produto"],["Administração","Via utilizada e localização anatômica da aplicação"],["Consentimento e certificado","Consentimento informado e duração esperada da proteção"]]}],"questions":[{"id":"13.1-match","ref":"13.1","type":"match","prompt":"Relacione cada descrição ao conceito correto.","labels":["Reações locais","Reações sistêmicas menores","Eventos raros"],"pairs":[{"text":"Letargia, anorexia, febre e vômito.","answer":"2"},{"text":"Dor e inchaço.","answer":"1"},{"text":"Urticária, anafilaxia e sarcoma de sítio de injeção felino.","answer":"3"}],"explanation":"Reações sistêmicas menores: Letargia, anorexia, febre e vômito. | Reações locais: Dor e inchaço. | Eventos raros: Urticária, anafilaxia e sarcoma de sítio de injeção felino."},{"id":"13.1-1","ref":"13.11","type":"choice","prompt":"Por que um evento que ocorre após a vacina não comprova, por si só, relação causal?","context":"","options":["Sequência temporal não comprova causalidade","Toda reação posterior prova culpa da vacina","Um evento raro nunca deve ser notificado","Reações após vacina dispensam investigação"],"answer":"Sequência temporal não comprova causalidade","explanation":"Porque a sequência temporal não demonstra causalidade. O evento pode estar relacionado à aplicação ou ter outra causa; é necessário investigar e registrar."},{"id":"13.2-a","ref":"13.2a","type":"choice","prompt":"Que região anatômica é recomendada no texto para a aplicação?","context":"","options":["Regiões distais dos membros; o texto destaca patas traseiras","Somente região entre as escápulas","Somente cabeça","Sempre no mesmo ponto, sem registrar"],"answer":"Regiões distais dos membros; o texto destaca patas traseiras","explanation":"Regiões distais dos membros; o texto destaca as patas traseiras."},{"id":"13.2-b","ref":"13.2b","type":"choice","prompt":"Por que o local de cada injeção deve ser registrado?","context":"","options":["Relacionar eventos ao local e orientar investigação e tratamento","Substituir o registro do lote","Dispensar qualquer investigação futura","Determinar a cor da vacina"],"answer":"Relacionar eventos ao local e orientar investigação e tratamento","explanation":"Para relacionar uma eventual massa ao local aplicado, acompanhar eventos e facilitar o planejamento diagnóstico e terapêutico."},{"id":"13.2-f1","ref":"13.2","type":"fill","prompt":"• Diâmetro maior que ____ cm.","answers":[["2"]],"explanation":"• Diâmetro maior que 2 cm.","referenceAnswers":["2"]},{"id":"13.2-f2","ref":"13.2","type":"fill","prompt":"• Persistência por ____ meses.","answers":[["3"]],"explanation":"• Persistência por 3 meses.","referenceAnswers":["3"]},{"id":"13.2-f3","ref":"13.2","type":"fill","prompt":"• Aumento de tamanho após ____ mês.","answers":[["1"]],"explanation":"• Aumento de tamanho após 1 mês.","referenceAnswers":["1"]},{"id":"13.2-c","ref":"13.2c","type":"choice","prompt":"Qual procedimento diagnóstico é indicado quando um desses critérios ocorre?","context":"","options":["Biópsia quando qualquer critério da regra 3-2-1 ocorrer","Ignorar a massa em qualquer tamanho","Esperar obrigatoriamente 3 anos","Investigar somente se os três critérios ocorrerem juntos"],"answer":"Biópsia quando qualquer critério da regra 3-2-1 ocorrer","explanation":"Biópsia da massa quando ocorrer qualquer um dos critérios da regra 3-2-1."},{"id":"13.3-a","ref":"13.3a","type":"choice","prompt":"A quem o veterinário deve notificar os eventos adversos suspeitos?","context":"","options":["Fabricante e autoridades reguladoras","Somente vizinhos do tutor","Somente redes sociais","Somente o fornecedor de ração"],"answer":"Fabricante e autoridades reguladoras","explanation":"Ao fabricante e às autoridades reguladoras."},{"id":"13.3-t1","ref":"13.3","type":"choice","prompt":"O que registrar no campo \"Data\"?","options":["Dia, mês e ano da vacinação","Nome da vacina e número do lote","Fabricante do produto","Via utilizada e localização anatômica da aplicação"],"answer":"Dia, mês e ano da vacinação","explanation":"Dia, mês e ano da vacinação"},{"id":"13.3-t2","ref":"13.3","type":"choice","prompt":"O que registrar no campo \"Identificação do produto\"?","options":["Nome da vacina e número do lote","Dia, mês e ano da vacinação","Fabricante do produto","Via utilizada e localização anatômica da aplicação"],"answer":"Nome da vacina e número do lote","explanation":"Nome da vacina e número do lote"},{"id":"13.3-t3","ref":"13.3","type":"choice","prompt":"O que registrar no campo \"Origem\"?","options":["Fabricante do produto","Dia, mês e ano da vacinação","Nome da vacina e número do lote","Via utilizada e localização anatômica da aplicação"],"answer":"Fabricante do produto","explanation":"Fabricante do produto"},{"id":"13.3-t4","ref":"13.3","type":"choice","prompt":"O que registrar no campo \"Administração\"?","options":["Via utilizada e localização anatômica da aplicação","Dia, mês e ano da vacinação","Nome da vacina e número do lote","Fabricante do produto"],"answer":"Via utilizada e localização anatômica da aplicação","explanation":"Via utilizada e localização anatômica da aplicação"},{"id":"13.3-t5","ref":"13.3","type":"choice","prompt":"O que registrar no campo \"Consentimento e certificado\"?","options":["Consentimento informado e duração esperada da proteção","Dia, mês e ano da vacinação","Nome da vacina e número do lote","Fabricante do produto"],"answer":"Consentimento informado e duração esperada da proteção","explanation":"Consentimento informado e duração esperada da proteção"}]},{"id":14,"title":"Saúde preventiva e revisão final de vacinação","group":"Vacinação","summary":["Vacinação faz parte da saúde preventiva completa.","Evitar doses desnecessárias sem abandonar a proteção indicada.","Associação entre vacinação e DRC não comprova causalidade."],"lesson":[{"type":"heading","text":"14.1 Responda."},{"type":"qa","question":"a) Além da vacinação, cite três componentes de uma avaliação preventiva regular.","answer":"Exemplos: controle parasitário, cuidados odontológicos e avaliação nutricional. Também se inclui avaliação comportamental."},{"type":"qa","question":"b) A idade avançada, isoladamente, significa perda da memória imunológica?","answer":"Não. Animais idosos geralmente mantêm memória imunológica; o reforço deve considerar o histórico e o risco individual."},{"type":"qa","question":"c) Uma associação entre revacinação frequente e DRC comprova causalidade? Explique.","answer":"Não. Associação estatística não demonstra que a vacinação causou DRC. O texto recomenda evitar aplicações desnecessárias, mas informa que a causalidade não foi comprovada."},{"type":"qa","question":"d) Qual mecanismo envolvendo células CRFK foi sugerido no texto?","answer":"Componentes de células renais felinas CRFK usadas na produção de algumas vacinas poderiam induzir anticorpos que reconhecem tecido renal. É uma hipótese, não prova de que a vacinação cause DRC."},{"type":"qa","question":"e) Nosódios homeopáticos substituem a imunização por vacinas?","answer":"Não. O texto informa que não imunizam contra doenças infecciosas e não apresentam evidências adequadas de eficácia."},{"type":"heading","text":"14.2 Desafio final"},{"type":"p","html":"Um abrigo recebe um cão de 8 semanas sem histórico vacinal e uma gata adulta que vive em grupo e tem acesso à rua."},{"type":"qa","question":"a) Qual é a prioridade vacinal na admissão e como continuar a série do cão?","answer":"Administrar as vacinas essenciais na admissão. No abrigo, repetir as doses essenciais do filhote a cada 2 a 3 semanas até 5 meses, conforme o protocolo descrito, considerando também a proteção contra doenças respiratórias."},{"type":"qa","question":"b) Que fatores devem orientar a indicação de FeLV para a gata?","answer":"Ocorrência regional de FeLV, acesso à rua, convivência em grupo e contato com gatos potencialmente infectados. O texto não permite concluir que a gata já tenha FeLV."},{"type":"qa","question":"c) Quais informações precisam ser registradas após cada aplicação?","answer":"Data, nome da vacina, lote, fabricante, via e local de aplicação; documentar também consentimento, especialmente no uso fora da bula, e duração esperada da proteção no certificado."},{"type":"heading","text":"14.3 Checklist para a prova: vacinação"},{"type":"p","html":"[  ] Diferencio vacinas essenciais, não essenciais e não recomendadas."},{"type":"p","html":"[  ] Reconheço os agentes essenciais caninos e felinos."},{"type":"p","html":"[  ] Explico as condições de indicação de raiva, leptospirose e FeLV."},{"type":"p","html":"[  ] Relaciono MDA, idade da última dose e janela de suscetibilidade."},{"type":"p","html":"[  ] Sei quando solicitar sorologia e reconheço suas limitações."},{"type":"p","html":"[  ] Diferencio o manejo vacinal de domicílios, abrigos e reprodutoras."},{"type":"p","html":"[  ] Reconheço eventos adversos e os critérios de investigação do SSIF."},{"type":"p","html":"[  ] Sei registrar a vacinação e evitar aplicações desnecessárias."}],"questions":[{"id":"14.1-a","ref":"14.1a","type":"choice","prompt":"Além da vacinação, cite três componentes de uma avaliação preventiva regular.","context":"","options":["Controle parasitário, odontologia e avaliação nutricional","Somente vacinação e nenhuma avaliação","Somente medição da pelagem","Somente pesagem, sem avaliar saúde"],"answer":"Controle parasitário, odontologia e avaliação nutricional","explanation":"Exemplos: controle parasitário, cuidados odontológicos e avaliação nutricional. Também se inclui avaliação comportamental."},{"id":"14.1-b","ref":"14.1b","type":"choice","prompt":"A idade avançada, isoladamente, significa perda da memória imunológica?","context":"","options":["Não; a memória costuma persistir, e o risco deve ser avaliado","Sim; toda memória desaparece aos 9 anos","Sim; toda vacinação é inútil em idosos","Não; idosos devem receber toda vacina mensalmente"],"answer":"Não; a memória costuma persistir, e o risco deve ser avaliado","explanation":"Não. Animais idosos geralmente mantêm memória imunológica; o reforço deve considerar o histórico e o risco individual."},{"id":"14.1-c","ref":"14.1c","type":"choice","prompt":"Uma associação entre revacinação frequente e DRC comprova causalidade? Explique.","context":"","options":["Não; associação não comprova causalidade","Sim; qualquer associação prova a causa","Sim; dispensa investigação adicional","Não; a associação prova proteção renal"],"answer":"Não; associação não comprova causalidade","explanation":"Não. Associação estatística não demonstra que a vacinação causou DRC. O texto recomenda evitar aplicações desnecessárias, mas informa que a causalidade não foi comprovada."},{"id":"14.1-d","ref":"14.1d","type":"choice","prompt":"Qual mecanismo envolvendo células CRFK foi sugerido no texto?","context":"","options":["Possíveis anticorpos contra tecido renal a partir de componentes CRFK","Produção obrigatória de cálculos pela vacina","Destruição comprovada de rins em todo gato vacinado","Infecção renal obrigatória por todas as vacinas"],"answer":"Possíveis anticorpos contra tecido renal a partir de componentes CRFK","explanation":"Componentes de células renais felinas CRFK usadas na produção de algumas vacinas poderiam induzir anticorpos que reconhecem tecido renal. É uma hipótese, não prova de que a vacinação cause DRC."},{"id":"14.1-e","ref":"14.1e","type":"choice","prompt":"Nosódios homeopáticos substituem a imunização por vacinas?","context":"","options":["Não; não substituem a imunização por vacinas","Sim; têm proteção comprovada equivalente","Sim; são vacinas essenciais globais","Sim; dispensam todos os reforços"],"answer":"Não; não substituem a imunização por vacinas","explanation":"Não. O texto informa que não imunizam contra doenças infecciosas e não apresentam evidências adequadas de eficácia."},{"id":"14.2-a","ref":"14.2a","type":"choice","prompt":"Qual é a prioridade vacinal na admissão e como continuar a série do cão?","context":"Um abrigo recebe um cão de 8 semanas sem histórico vacinal e uma gata adulta que vive em grupo e tem acesso à rua.","options":["Vacinar na entrada; repetir a cada 2 a 3 semanas até 5 meses","Esperar o cão completar 5 anos","Vacinar somente após aparecerem sintomas","Aplicar uma dose e encerrar a série com 8 semanas"],"answer":"Vacinar na entrada; repetir a cada 2 a 3 semanas até 5 meses","explanation":"Administrar as vacinas essenciais na admissão. No abrigo, repetir as doses essenciais do filhote a cada 2 a 3 semanas até 5 meses, conforme o protocolo descrito, considerando também a proteção contra doenças respiratórias."},{"id":"14.2-b","ref":"14.2b","type":"choice","prompt":"Que fatores devem orientar a indicação de FeLV para a gata?","context":"Um abrigo recebe um cão de 8 semanas sem histórico vacinal e uma gata adulta que vive em grupo e tem acesso à rua.","options":["Ocorrência regional, acesso à rua e contato com outros gatos","Somente o comprimento da cauda","Somente a idade do tutor","Somente a cor das orelhas"],"answer":"Ocorrência regional, acesso à rua e contato com outros gatos","explanation":"Ocorrência regional de FeLV, acesso à rua, convivência em grupo e contato com gatos potencialmente infectados. O texto não permite concluir que a gata já tenha FeLV."},{"id":"14.2-c","ref":"14.2c","type":"choice","prompt":"Quais informações precisam ser registradas após cada aplicação?","context":"Um abrigo recebe um cão de 8 semanas sem histórico vacinal e uma gata adulta que vive em grupo e tem acesso à rua.","options":["Data, produto, lote, fabricante, via, local e consentimento","Somente o nome do animal","Somente o preço da aplicação","Somente o número de doses anteriores"],"answer":"Data, produto, lote, fabricante, via, local e consentimento","explanation":"Data, nome da vacina, lote, fabricante, via e local de aplicação; documentar também consentimento, especialmente no uso fora da bula, e duração esperada da proteção no certificado."}]}],"sources":[{"name":"WSAVA • Diretrizes de vacinação, 2024","url":"https://wsava.org/wp-content/uploads/2024/04/WSAVA-Vaccination-guidelines-2024.pdf"},{"name":"Texto e estudo dirigido fornecidos","url":"guia-com-respostas.pdf"}]};
